window.GITA=window.GITA||{};GITA.capitulos=GITA.capitulos||{};GITA.capitulos[12]={"numero": 12, "titulo": "El yoga de la devoción", "versos": [{"n": 1, "hablante": "arjuna", "sa": ["अर्जुन उवाच ।", "एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते ।", "ये चाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः ॥१॥"], "iast": ["arjuna uvāca", "evaṃ satata-yuktā ye bhaktās tvāṃ paryupāsate", "ye cāpy akṣaram avyaktaṃ teṣāṃ ke yoga-vittamāḥ"], "rojas": [], "t": "<span class=\"vt-parte\">Los <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devotos</a> que, siempre <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unidos</a> a ti de este modo, te <a class=\"t\" href=\"glosario.html#upasana\" data-t=\"upasana\">adoran</a>, y los que adoran lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a>, lo <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">no manifiesto</a>: ¿quiénes de ellos conocen mejor el <a class=\"t\" href=\"glosario.html#yoga\" data-t=\"yoga\">yoga</a>?</span>", "palabras": [{"iast": "arjunaḥ", "sa": "अर्जुनः", "gram": "nom. sg. m.", "es": "Arjuna", "ref": "arjuna"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "evam", "sa": "एवम्", "gram": "adv.", "es": "así, de este modo"}, {"iast": "satata-yuktāḥ", "sa": "सततयुक्ताः", "gram": "nom. pl. m. comp.", "es": "siempre unidos", "ref": "yukta", "analisis": "satata (continuo, siempre) + yukta (unido), de √yuj (uncir, unir)"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron. rel.", "es": "los que"}, {"iast": "bhaktāḥ", "sa": "भक्ताः", "gram": "nom. pl. m.", "es": "devotos", "ref": "bhakti", "analisis": "de √bhaj (participar, adorar)"}, {"iast": "tvām", "sa": "त्वाम्", "gram": "acc. sg. pron.", "es": "a ti"}, {"iast": "paryupāsate", "sa": "पर्युपासते", "gram": "3 pl. pres. med.", "es": "adoran", "ref": "upasana", "analisis": "pari (del todo, en torno) + upa (junto a) + √ās (sentarse)"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron. rel.", "es": "los que"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "también"}, {"iast": "akṣaram", "sa": "अक्षरम्", "gram": "acc. sg. n.", "es": "lo imperecedero", "ref": "aksara", "analisis": "a- (no) + √kṣar (fluir, desgastarse)"}, {"iast": "avyaktam", "sa": "अव्यक्तम्", "gram": "acc. sg. n.", "es": "lo no manifiesto", "ref": "avyakta", "analisis": "a- (no) + vyakta (manifiesto), de vi-√añj (hacer visible)"}, {"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m. pron.", "es": "de ellos"}, {"iast": "ke", "sa": "के", "gram": "nom. pl. m. pron. interr.", "es": "¿quiénes?"}, {"iast": "yoga-vittamāḥ", "sa": "योगवित्तमाः", "gram": "nom. pl. m. superl.", "es": "los que mejor conocen el yoga", "ref": "yoga", "analisis": "yoga + vid (conocedor), de √vid (saber) + -tama (sufijo de superlativo)"}], "nota": "<p><em>Evam</em>, «de este modo», remite al último verso del capítulo anterior (<a class=\"vref\" href=\"capitulo-11.html#v55\" data-v=\"11.55\">11.55</a>): obrar para Kṛṣṇa, tenerlo por meta suprema, ser su devoto, sin apego y sin enemistad hacia ningún ser. Así lo entienden <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> y <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>.</p><p>La pregunta enfrenta a dos clases de personas por lo que adoran: a Kṛṣṇa, «tú», o «lo imperecedero, lo no manifiesto», las dos palabras con que el capítulo 8 había nombrado la meta suprema (<a class=\"vref\" href=\"capitulo-08.html#v21\" data-v=\"8.21\">8.21</a>). <em>Yoga-vittama</em> es el superlativo de <em>yoga-vid</em>, «conocedor del yoga»: ¿quiénes lo conocen mejor? En la respuesta, Kṛṣṇa cambiará de palabra y dirá quiénes son los «más unidos en yoga», <em>yukta-tama</em> (<a class=\"vref\" href=\"capitulo-12.html#v2\" data-v=\"12.2\">12.2</a>). Qué es ese imperecedero no manifiesto es una de las cuestiones más discutidas entre las escuelas (véanse las interpretaciones).</p>", "interp": [{"titulo": "Lo imperecedero es brahman sin atributos", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, los primeros son los devotos que, sin otro refugio, meditan en Kṛṣṇa en la forma universal que acaba de mostrar; los segundos, los que han renunciado a todo deseo y a toda acción y meditan en <a class=\"t\" href=\"glosario.html#brahman\" data-t=\"brahman\">brahman</a>, imperecedero, y no manifiesto porque está libre de todo condicionamiento y ningún órgano de los sentidos lo alcanza. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden también como el brahman sin atributos (<em>nirguṇa</em>, <em>nirviśeṣa</em>); Madhusūdana repite casi a la letra la descripción de Śaṅkara, y Śrīdhara ve igualmente en los primeros a los que adoran la forma universal. Śrīdhara abre el capítulo con un verso propio que resume su propósito: decidir qué es mejor, la adoración de lo que tiene atributos o la de lo que no los tiene.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Por qué pregunta Arjuna", "html": "<p><a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> explica la pregunta por lo que Kṛṣṇa ha dicho antes: había declarado superior al devoto (al final del capítulo 11 y en <a class=\"vref\" href=\"capitulo-09.html#v31\" data-v=\"9.31\">9.31</a>), pero también al sabio (<a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a>) y al que tiene conocimiento (<a class=\"vref\" href=\"capitulo-04.html#v36\" data-v=\"4.36\">4.36</a>); Arjuna, ante los dos elogios, quiere saber cuál es mejor. Para <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, la duda está en lo que Kṛṣṇa quiere decir con «mí»: a veces lo sin forma (<a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>: «Vāsudeva es todo»), a veces lo que tiene forma (<a class=\"vref\" href=\"capitulo-11.html#v53\" data-v=\"11.53\">11.53</a>). Arjuna, que busca la liberación, pregunta para saber cuál de los dos caminos le corresponde a él. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, en la introducción al capítulo, da una razón parecida a la de Śrīdhara: los capítulos anteriores habían enseñado a adorar tanto lo imperecedero, libre de todo condicionamiento, como al Señor, y el 11 había mostrado la forma universal para que se la adorase; Arjuna quiere saber cuál de las dos es mejor.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Lo imperecedero es el sí-mismo individual", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, los primeros adoran a Kṛṣṇa como un océano de cualidades sin límite, la belleza, la afabilidad, la omnisciencia, la voluntad que siempre se cumple; los segundos adoran «lo imperecedero», que aquí no es el Señor, sino el sí-mismo individual en su naturaleza propia (<em>pratyag-ātman</em>), no manifiesto porque no lo captan los ojos ni los demás sentidos. La pregunta, para él, no es cuál de los dos objetos es más alto, sino quiénes llegan antes a su meta: lo muestra, dice, la respuesta de <a class=\"vref\" href=\"capitulo-12.html#v7\" data-v=\"12.7\">12.7</a>, «no tardo, oh Pārtha».</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Lo no manifiesto es la diosa Śrī", "html": "<p>Para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, lo no manifiesto es la naturaleza primordial (<a class=\"t\" href=\"glosario.html#prakrti\" data-t=\"prakrti\">prakṛti</a>), y lo imperecedero, un atributo suyo; pero esa naturaleza, en su aspecto consciente, es la diosa <a class=\"t\" href=\"glosario.html#sri\" data-t=\"sri\">Śrī</a>, y cita textos según los cuales también su adoración lleva a la liberación. Rechaza la lectura que opone a Kṛṣṇa un brahman distinto de él, porque el brahman supremo no es otro que el Señor. Arjuna, dice, conoce la respuesta, pero pregunta para aprender las razones sutiles. Su comentador Jayatīrtha lo resume: «lo no manifiesto es Śrī».</p>", "trad": "dvaita", "tradNombre": "Dvaita"}, {"titulo": "Personalistas e impersonalistas", "html": "<p>Prabhupāda traduce la segunda mitad como «los que adoran el Brahman impersonal, lo no manifiesto», y presenta la pregunta como la de dos clases de trascendentalistas: los personalistas, que sirven a Kṛṣṇa, y los impersonalistas, que meditan en el Brahman impersonal. Arjuna, apegado a la forma personal de Kṛṣṇa, quiere saber, dice, si su posición es segura.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)"}, {"n": 2, "hablante": "krsna", "sa": ["श्रीभगवानुवाच ।", "मय्यावेश्य मनो ये मां नित्ययुक्ता उपासते ।", "श्रद्धया परयोपेतास्ते मे युक्ततमा मताः ॥२॥"], "iast": ["śrī-bhagavān uvāca", "mayy āveśya mano ye māṃ nitya-yuktā upāsate", "śraddhayā parayopetās te me yukta-tamā matāḥ"], "rojas": [1, 2], "t": "<span class=\"vt-parte voz-krsna\">Los que hacen entrar en mí la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> y, siempre <a class=\"t\" href=\"glosario.html#yukta\" data-t=\"yukta\">unidos</a>, me <a class=\"t\" href=\"glosario.html#upasana\" data-t=\"upasana\">veneran</a>, dotados de una <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a> suprema, ésos son para mí los más unidos en yoga.</span>", "palabras": [{"iast": "śrī-bhagavān", "sa": "श्रीभगवान्", "gram": "nom. sg. m. comp.", "es": "el glorioso Señor", "ref": "bhagavan", "analisis": "śrī (gloria) + bhagavat (el Señor)"}, {"iast": "uvāca", "sa": "उवाच", "gram": "3 sg. pf. act.", "es": "dijo", "analisis": "√vac (hablar)"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "āveśya", "sa": "आवेश्य", "gram": "abs.", "es": "haciendo entrar, fijando", "analisis": "ā-√viś (entrar), causativo"}, {"iast": "manaḥ", "sa": "मनः", "gram": "acc. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron. rel.", "es": "los que"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "nitya-yuktāḥ", "sa": "नित्ययुक्ताः", "gram": "nom. pl. m. comp.", "es": "siempre unidos", "ref": "yukta", "analisis": "nitya (constante, siempre) + yukta (unido)"}, {"iast": "upāsate", "sa": "उपासते", "gram": "3 pl. pres. med.", "es": "veneran", "ref": "upasana", "analisis": "upa (junto a) + √ās (sentarse)"}, {"iast": "śraddhayā", "sa": "श्रद्धया", "gram": "instr. sg. f.", "es": "con fe", "ref": "sraddha"}, {"iast": "parayā", "sa": "परया", "gram": "instr. sg. f.", "es": "suprema"}, {"iast": "upetāḥ", "sa": "उपेताः", "gram": "nom. pl. m. ppp.", "es": "dotados", "analisis": "upa-√i (acercarse, llegar a tener)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ésos"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "para mí, a mi juicio"}, {"iast": "yukta-tamāḥ", "sa": "युक्ततमाः", "gram": "nom. pl. m. superl.", "es": "los más unidos en yoga", "ref": "yukta", "analisis": "yukta (unido) + -tama (sufijo de superlativo)"}, {"iast": "matāḥ", "sa": "मताः", "gram": "nom. pl. m. ppp.", "es": "considerados", "analisis": "√man (pensar, juzgar)"}], "nota": "<p>Kṛṣṇa responde primero a favor de los que lo adoran a él. <em>Āveśya</em>, «haciendo entrar», es el verbo de <a class=\"vref\" href=\"capitulo-08.html#v10\" data-v=\"8.10\">8.10</a>, donde el yogui hace entrar el aliento entre las cejas: aquí es la mente lo que entra en Kṛṣṇa. <em>Nitya-yukta</em>, «siempre unidos», recoge el <em>satata-yukta</em> de la pregunta (<a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a>), y la fórmula final, <em>me yukta-tamā matāḥ</em>, «son para mí los más unidos en yoga», es la misma con que <a class=\"vref\" href=\"capitulo-06.html#v47\" data-v=\"6.47\">6.47</a> había declarado el mejor de los yoguis al que lo adora con fe, con el ser interior puesto en él.</p><p>El verso no dice en qué forma lo veneran; los comentaristas lo precisan de distintos modos (véanse las interpretaciones). Tampoco dice todavía nada de los otros: la respuesta sobre ellos llega en <a class=\"vref\" href=\"capitulo-12.html#v3\" data-v=\"12.3\">12.3</a>–<a class=\"vref\" href=\"capitulo-12.html#v5\" data-v=\"12.5\">12.5</a>.</p>", "interp": [{"titulo": "Pasan los días y las noches pensando en él", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, son los más unidos porque pasan los días y las noches con el pensamiento puesto en él, el Señor supremo en su forma universal; la misma razón da <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>. Se adelanta a la objeción: ¿no lo son, entonces, los otros? No es eso, responde, sino que de ellos hay que decir otra cosa, y remite a los versos siguientes. La misma objeción la plantea <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> al introducir <a class=\"vref\" href=\"capitulo-12.html#v3\" data-v=\"12.3\">12.3</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Una respuesta a la medida de Arjuna", "html": "<p>Para <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, Kṛṣṇa, que todo lo sabe, ve que Arjuna sólo está capacitado para el conocimiento de lo que tiene atributos, y por eso elogia primero ese camino, para hacérselo atractivo. Hacer entrar la mente en él es volverla del todo suya, como la laca que se tiñe de bermellón. Al introducir <a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a> lo aclara: la censura del otro camino sirve sólo para alabar éste, y en verdad los que mejor conocen el yoga son los que adoran lo imperecedero.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Lo alcanzan pronto y con facilidad", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, fijan en él la mente porque les es querido por encima de todo, y desean estar unidos a él sin interrupción. Ser «los más unidos» significa, para él, que lo alcanzan con facilidad y pronto.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "¿En qué forma?", "html": "<p>El verso dice sólo «en mí». <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo precisa como el Señor supremo en la forma universal del capítulo 11, y lo llama también omnisciente; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, como el Señor dotado de omnisciencia y demás cualidades (en <a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a> había hablado también de la forma universal); <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, como Vāsudeva, el brahman con atributos y con forma. Prabhupāda traduce «los que fijan la mente en mi forma personal»: la «forma personal» no está en el sánscrito, pero recoge la lectura de su escuela.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "dos-maneras-de-adorar"}, {"n": 3, "hablante": "krsna", "sa": ["ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते ।", "सर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम् ॥३॥"], "iast": ["ye tv akṣaram anirdeśyam avyaktaṃ paryupāsate", "sarvatra-gam acintyaṃ ca kūṭa-stham acalaṃ dhruvam"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero los que adoran lo <a class=\"t\" href=\"glosario.html#aksara\" data-t=\"aksara\">imperecedero</a>, lo indefinible, lo <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">no manifiesto</a>, lo que está en todas partes y lo impensable, lo <a class=\"t\" href=\"glosario.html#kutastha\" data-t=\"kutastha\">inmutable</a>, lo inmóvil, lo firme,</span>", "palabras": [{"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron. rel.", "es": "los que"}, {"iast": "tu", "sa": "तु", "gram": "part.", "es": "pero"}, {"iast": "akṣaram", "sa": "अक्षरम्", "gram": "acc. sg. n.", "es": "lo imperecedero", "ref": "aksara"}, {"iast": "anirdeśyam", "sa": "अनिर्देश्यम्", "gram": "acc. sg. n. gerundivo", "es": "indefinible, que no puede señalarse", "analisis": "a- (no) + nir-√diś (señalar, designar)"}, {"iast": "avyaktam", "sa": "अव्यक्तम्", "gram": "acc. sg. n.", "es": "lo no manifiesto", "ref": "avyakta"}, {"iast": "paryupāsate", "sa": "पर्युपासते", "gram": "3 pl. pres. med.", "es": "adoran", "ref": "upasana", "analisis": "pari + upa + √ās"}, {"iast": "sarvatra-gam", "sa": "सर्वत्रगम्", "gram": "acc. sg. n. comp.", "es": "que está en todas partes", "analisis": "sarvatra (en todas partes) + ga (que va), de √gam (ir)"}, {"iast": "acintyam", "sa": "अचिन्त्यम्", "gram": "acc. sg. n. gerundivo", "es": "impensable", "analisis": "a- (no) + √cint (pensar)"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "kūṭa-stham", "sa": "कूटस्थम्", "gram": "acc. sg. n. comp.", "es": "inmutable", "ref": "kutastha", "analisis": "kūṭa (cima, montón, mazo; también engaño; por tradición, «yunque») + stha (que está), de √sthā (estar)"}, {"iast": "acalam", "sa": "अचलम्", "gram": "acc. sg. n.", "es": "inmóvil", "analisis": "a- (no) + cala (que se mueve), de √cal (moverse)"}, {"iast": "dhruvam", "sa": "ध्रुवम्", "gram": "acc. sg. n.", "es": "firme, constante"}], "nota": "<p><a class=\"vref\" href=\"capitulo-12.html#v3\" data-v=\"12.3\">12.3</a> y <a class=\"vref\" href=\"capitulo-12.html#v4\" data-v=\"12.4\">12.4</a> forman una sola frase. Siete adjetivos describen lo imperecedero, como observa <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>: no se puede señalar con palabras (<em>anirdeśya</em>), no es manifiesto, está en todas partes, no se puede pensar, es <em>kūṭa-stha</em>, no se mueve y es firme. Varios recuerdan la descripción del sí-mismo en el capítulo 2: presente en todo e inmóvil (<em>sarva-gata</em>, <em>acala</em>, <a class=\"vref\" href=\"capitulo-02.html#v24\" data-v=\"2.24\">2.24</a>), no manifiesto e impensable (<a class=\"vref\" href=\"capitulo-02.html#v25\" data-v=\"2.25\">2.25</a>).</p><p><em>Kūṭa-stha</em> aparece también en <a class=\"vref\" href=\"capitulo-06.html#v8\" data-v=\"6.8\">6.8</a> y en <a class=\"vref\" href=\"capitulo-15.html#v16\" data-v=\"15.16\">15.16</a>. En esta edición se traduce «inmutable», como en 6.8; la imagen que hay detrás se discute (véase la ficha <a class=\"t\" href=\"glosario.html#kutastha\" data-t=\"kutastha\">kūṭastha</a>). <em>Paryupāsate</em>, «adoran», es el mismo verbo de la pregunta (<a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a>); sobre su sentido, véase la ficha <a class=\"t\" href=\"glosario.html#upasana\" data-t=\"upasana\">upāsana</a>.</p>", "interp": [{"titulo": "Qué es adorar", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> define aquí la <em>upāsana</em>: acercarse a lo que se adora tal como lo presentan las escrituras, haciéndolo objeto del pensamiento, y permanecer en ello largo tiempo con una corriente continua de la misma idea, «como un hilo de aceite que se vierte». Lo imperecedero está en todas partes como el espacio, y es impensable porque, al no ser manifiesto, tampoco lo alcanza la mente. <em>Kūṭa</em>, explica, es lo que parece bueno y por dentro es malo, como en «falso testimonio» (<em>kūṭa-sākṣya</em>): la <a class=\"t\" href=\"glosario.html#maya\" data-t=\"maya\">māyā</a>, semilla del ciclo de renacimientos; lo imperecedero «está en ella» como quien la gobierna. O bien: «está como un montón», inmóvil.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sobre la ignorancia, como sustrato", "html": "<p><a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> entiende <em>kūṭa-stha</em> como lo que está en el mundo de la māyā como su sustrato. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explica con la moneda falsa (<em>kūṭa-kārṣāpaṇa</em>): <em>kūṭa</em> es lo que, siendo falso, se tiene por verdadero, y así la ignorancia y todo lo que produce; lo imperecedero es su sustrato. Añade cómo lo «adoran» estos buscadores: escuchando la enseñanza de las Upaniṣads, reflexionando sobre ella y contemplándola sin interrupción, «como un hilo de aceite».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Los rasgos del sí-mismo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, los siete adjetivos describen el sí-mismo individual. Es indefinible porque, distinto del cuerpo, no puede nombrarse con palabras como «dios» u «hombre»; está en todas partes porque habita cuerpos de toda clase, sin poder pensarse con la forma de ninguno; es <em>kūṭa-stha</em> porque es común a todos, sin relación con las formas particulares de cada cuerpo; inmóvil porque no deja su naturaleza propia, y por eso firme, eterno.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Los rasgos de la naturaleza primordial", "html": "<p>Para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, que identifica lo no manifiesto con la naturaleza primordial y con la diosa Śrī (<a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a>), estos adjetivos le convienen a ella: indefinible, como, según él, llama a la māyā el <em>Bhāgavata Purāṇa</em> (1.17.20); en todas partes e impensable. <em>Kūṭa</em> es para él el espacio, y <em>kūṭa-stha</em>, la que está en el espacio.</p>", "trad": "dvaita", "tradNombre": "Dvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "dos-maneras-de-adorar"}, {"n": 4, "hablante": "krsna", "sa": ["संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः ।", "ते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः ॥४॥"], "iast": ["saṃniyamyendriya-grāmaṃ sarvatra sama-buddhayaḥ", "te prāpnuvanti mām eva sarva-bhūta-hite ratāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">sujetando el conjunto de los <a class=\"t\" href=\"glosario.html#indriya\" data-t=\"indriya\">sentidos</a>, con el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> ecuánime en todo, entregados al bien de todos los seres, también ellos llegan a mí.</span>", "palabras": [{"iast": "saṃniyamya", "sa": "संनियम्य", "gram": "abs.", "es": "sujetando del todo", "analisis": "sam (del todo) + ni-√yam (refrenar, sujetar)"}, {"iast": "indriya-grāmam", "sa": "इन्द्रियग्रामम्", "gram": "acc. sg. m. comp.", "es": "el conjunto de los sentidos", "ref": "indriya", "analisis": "indriya (sentido) + grāma (conjunto, aldea)"}, {"iast": "sarvatra", "sa": "सर्वत्र", "gram": "adv.", "es": "en todo, en todas partes"}, {"iast": "sama-buddhayaḥ", "sa": "समबुद्धयः", "gram": "nom. pl. m. comp.", "es": "de entendimiento ecuánime", "ref": "buddhi", "analisis": "sama (igual, ecuánime) + buddhi (entendimiento)"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "ellos"}, {"iast": "prāpnuvanti", "sa": "प्राप्नुवन्ति", "gram": "3 pl. pres. act.", "es": "alcanzan, llegan a", "analisis": "pra-√āp (alcanzar)"}, {"iast": "mām", "sa": "माम्", "gram": "acc. sg. pron.", "es": "a mí"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "precisamente"}, {"iast": "sarva-bhūta-hite", "sa": "सर्वभूतहिते", "gram": "loc. sg. n. comp.", "es": "en el bien de todos los seres", "analisis": "sarva (todo) + bhūta (ser) + hita (bien, provecho)"}, {"iast": "ratāḥ", "sa": "रताः", "gram": "nom. pl. m. ppp.", "es": "entregados, que se complacen", "analisis": "√ram (complacerse)"}], "nota": "<p>Tres condiciones acompañan esta adoración: el dominio de los sentidos, la ecuanimidad y la entrega al bien de todos los seres, la misma expresión con que <a class=\"vref\" href=\"capitulo-05.html#v25\" data-v=\"5.25\">5.25</a> describe a los que alcanzan la extinción en brahman. Y la respuesta sorprende después de <a class=\"vref\" href=\"capitulo-12.html#v2\" data-v=\"12.2\">12.2</a>: también ellos llegan a Kṛṣṇa. <em>Mām eva</em> es enfático, «a mí precisamente»; «también ellos» recoge la glosa de <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, <em>te &#x27;pi</em>, «también ésos».</p><p><em>Sarvatra</em>, «en todo», lo entiende <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> como «en todo momento», ante lo deseado y lo no deseado; Madhusūdana, como «ante todos los objetos», sin alegría ni pesar, sin atracción ni aversión; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como «ante todos los sí-mismos», sea cual sea el cuerpo, de dios o de hombre, que habiten.</p>", "interp": [{"titulo": "De ellos no hay nada que decir", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, de éstos no hace falta decir que llegan a él: ya se dijo que el sabio es su propio ser (<a class=\"vref\" href=\"capitulo-07.html#v18\" data-v=\"7.18\">7.18</a>), verso que también cita aquí <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, y de quienes son la forma misma del Señor no tiene sentido decir si son o no los más unidos en yoga. Al introducir <a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a> añade que con «llegan a mí» Kṛṣṇa ha mostrado que éstos alcanzan la liberación por sí mismos, mientras que a los otros, que dependen de él, les dice «yo soy quien los saca» del océano del saṃsāra (<a class=\"vref\" href=\"capitulo-12.html#v7\" data-v=\"12.7\">12.7</a>).</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Llegan a un sí-mismo semejante al suyo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, «llegan a mí» quiere decir que alcanzan su propio sí-mismo, libre del ciclo de renacimientos, de forma semejante a la de Kṛṣṇa. Lo apoya en <a class=\"vref\" href=\"capitulo-14.html#v2\" data-v=\"14.2\">14.2</a>, «llegados a la semejanza conmigo», y en la <em>Muṇḍaka Upaniṣad</em> (3.1.3): el que está sin mancha «alcanza la igualdad suprema». Y recuerda que el capítulo 15 distinguirá del brahman supremo el <em>akṣara</em> llamado <em>kūṭa-stha</em> (<a class=\"vref\" href=\"capitulo-15.html#v16\" data-v=\"15.16\">15.16</a>–<a class=\"vref\" href=\"capitulo-15.html#v17\" data-v=\"15.17\">15.17</a>).</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Llegan, pero por un camino indirecto", "html": "<p>Prabhupāda reconoce que los que no adoran directamente a Kṛṣṇa, sino por un proceso indirecto, alcanzan al fin la misma meta, y lo une a <a class=\"vref\" href=\"capitulo-07.html#v19\" data-v=\"7.19\">7.19</a>: el sabio, al cabo de muchos nacimientos, se entrega a Vāsudeva. Pero añade que suele haber mucha penitencia antes de esa entrega, y que para el hombre común este método impersonal es muy difícil.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "dos-maneras-de-adorar"}, {"n": 5, "hablante": "krsna", "sa": ["क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम् ।", "अव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते ॥५॥"], "iast": ["kleśo 'dhikataras teṣām avyaktāsakta-cetasām", "avyaktā hi gatir duḥkhaṃ dehavadbhir avāpyate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Mayor es el esfuerzo de los que tienen la mente apegada a lo <a class=\"t\" href=\"glosario.html#avyakta\" data-t=\"avyakta\">no manifiesto</a>, porque la meta no manifiesta la alcanzan con dificultad los que tienen cuerpo.</span>", "palabras": [{"iast": "kleśaḥ", "sa": "क्लेशः", "gram": "nom. sg. m.", "es": "esfuerzo penoso, fatiga", "analisis": "√kliś (atormentar, fatigar)"}, {"iast": "adhikataraḥ", "sa": "अधिकतरः", "gram": "nom. sg. m. comparativo", "es": "mayor", "analisis": "adhika (mucho, más) + -tara (sufijo de comparativo)"}, {"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m. pron.", "es": "de ellos"}, {"iast": "avyaktāsakta-cetasām", "sa": "अव्यक्तासक्तचेतसाम्", "gram": "gen. pl. m. comp.", "es": "de los que tienen la mente apegada a lo no manifiesto", "ref": "avyakta", "analisis": "avyakta (lo no manifiesto) + āsakta (apegado), de ā-√sañj (adherirse) + cetas (mente)"}, {"iast": "avyaktā", "sa": "अव्यक्ता", "gram": "nom. sg. f.", "es": "no manifiesta", "ref": "avyakta"}, {"iast": "hi", "sa": "हि", "gram": "part.", "es": "pues"}, {"iast": "gatiḥ", "sa": "गतिः", "gram": "nom. sg. f.", "es": "meta; también ida, camino", "analisis": "√gam (ir)"}, {"iast": "duḥkham", "sa": "दुःखम्", "gram": "adv.", "es": "con dificultad, penosamente", "ref": "duhkha"}, {"iast": "dehavadbhiḥ", "sa": "देहवद्भिः", "gram": "instr. pl. m.", "es": "por los que tienen cuerpo", "analisis": "deha (cuerpo) + -vat (que posee)"}, {"iast": "avāpyate", "sa": "अवाप्यते", "gram": "3 sg. pres. pas.", "es": "es alcanzada", "analisis": "ava-√āp (alcanzar)"}], "nota": "<p><em>Adhika-tara</em>, «mayor», es un comparativo: no dice que el otro camino no cueste, sino que éste cuesta más. Así lo entienden <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, que reconocen que también el esfuerzo de los devotos es grande; <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, en cambio, dice que para los devotos no hay fatiga alguna (<a class=\"vref\" href=\"capitulo-12.html#v6\" data-v=\"12.6\">12.6</a>). La razón está en la segunda mitad: lo no manifiesto es una meta difícil para quien tiene cuerpo. Madhusūdana resume así la respuesta de los versos 2 a 5: la meta es la misma, pero son mejores los que llegan a ella por un medio fácil que los que llegan por uno difícil.</p><p><em>Āsakta</em>, «apegado», no tiene aquí sentido negativo: es la palabra de <a class=\"vref\" href=\"capitulo-07.html#v1\" data-v=\"7.1\">7.1</a>, «con la mente apegada a mí».</p>", "interp": [{"titulo": "Dejar de identificarse con el cuerpo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el esfuerzo es mayor para los que tienen lo imperecedero por sí-mismo y ven la verdad suprema, porque tienen que abandonar la identificación con el cuerpo. Y anuncia que de la conducta de estos buscadores se hablará más adelante: la encuentra en los rasgos que empiezan en <a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> detalla el esfuerzo: renunciar a toda acción, acudir a un maestro y examinar las frases del Vedānta para deshacer, una por una, las ideas erróneas, «un gran trabajo, a la vista de todos».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La mente que toma el cuerpo por el sí-mismo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, lo difícil es la actividad de la mente dirigida a lo no manifiesto, porque los que tienen cuerpo toman el cuerpo por el sí-mismo. Con ello introduce los versos siguientes, en los que, dice, Kṛṣṇa muestra con toda claridad que los que adoran al Señor son los más unidos en yoga.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El Señor da los medios a su devoto", "html": "<p>Para <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, el camino que pasa por la adoración de lo no manifiesto exige un dominio extremo de los sentidos, ecuanimidad ante todo, la entrega al bien de todos los seres, buena conducta y devoción a <a class=\"t\" href=\"glosario.html#visnu\" data-t=\"visnu\">Viṣṇu</a>; sin eso no se llega a ver directamente lo no manifiesto ni la diosa concede su gracia, y aun así no hay liberación sin adorar al Señor. En cambio, los devotos del Señor se liberan sin necesidad de adorar lo no manifiesto, y es el propio Señor quien da a su devoto esos medios. Por eso este camino es el más penoso.</p>", "trad": "dvaita", "tradNombre": "Dvaita"}, {"titulo": "Un camino natural para el alma encarnada", "html": "<p>Prabhupāda llama a los primeros <em>jñāna-yogīs</em> y a los segundos <em>bhakti-yogīs</em>: el <em>jñāna-yoga</em>, aunque lleve a la misma meta, es muy penoso, y el <em>bhakti-yoga</em> es más fácil y natural para el alma encarnada. Por eso el devoto adora a Kṛṣṇa en la imagen del templo (<em>arcā-vigraha</em>), que no es un ídolo, sino una forma en la que el Señor acepta el servicio; la compara con un buzón autorizado por el correo. Concluye que la concentración en lo no manifiesto «no debe fomentarse nunca, en ningún momento, especialmente en esta era».</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Mayor es el esfuerzo de los que tienen la mente apegada a lo no manifiesto, porque a los que se identifican con el cuerpo les cuesta mantener la mente en lo no manifiesto.", "nota": "<p><em>Gati</em>, de √<em>gam</em> «ir», puede ser la meta a la que se va o el ir mismo. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la entienden como la meta, lo imperecedero; es la traducción principal. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> la entiende como el movimiento de la mente hacia lo no manifiesto, y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, como la firmeza (<em>niṣṭhā</em>) en él; <a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a>, como el camino. <em>Dehavat</em>, «el que tiene cuerpo», lo glosan Śaṅkara, Rāmānuja, Śrīdhara y Madhusūdana como «el que se identifica con el cuerpo»: la dificultad no está en tener cuerpo, sino en tomarlo por uno mismo.</p>"}], "ens": "dos-maneras-de-adorar"}, {"n": 6, "hablante": "krsna", "sa": ["ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः ।", "अनन्येनैव योगेन मां ध्यायन्त उपासते ॥६॥"], "iast": ["ye tu sarvāṇi karmāṇi mayi saṃnyasya mat-parāḥ", "ananyenaiva yogena māṃ dhyāyanta upāsate"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero a los que, depositando en mí todas sus <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a> y teniéndome por meta suprema, me <a class=\"t\" href=\"glosario.html#upasana\" data-t=\"upasana\">adoran</a> meditando en mí con un yoga que no se dirige a ningún otro,</span>", "palabras": [{"iast": "ye", "sa": "ये", "gram": "nom. pl. m. pron. rel.", "es": "los que"}, {"iast": "tu", "sa": "तु", "gram": "part.", "es": "pero"}, {"iast": "sarvāṇi", "sa": "सर्वाणि", "gram": "ac. pl. n. adj.", "es": "todas"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "ac. pl. n.", "es": "las acciones", "ref": "karma"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "saṃnyasya", "sa": "संन्यस्य", "gram": "abs.", "es": "depositando, entregando", "ref": "sannyasa", "analisis": "sam-ni-√as (arrojar, depositar por completo)"}, {"iast": "mat-parāḥ", "sa": "मत्पराः", "gram": "nom. pl. m. adj.", "es": "que me tienen por lo supremo", "analisis": "mad (yo) + para (supremo, meta última)"}, {"iast": "ananyena", "sa": "अनन्येन", "gram": "instr. sg. m. adj.", "es": "que no se dirige a otro", "ref": "ananya-bhakti", "analisis": "an-anya (no otro)"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "solamente, precisamente"}, {"iast": "yogena", "sa": "योगेन", "gram": "instr. sg. m.", "es": "con un yoga", "ref": "yoga"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "dhyāyantaḥ", "sa": "ध्यायन्तः", "gram": "nom. pl. m. part. pres.", "es": "meditando", "ref": "dhyana", "analisis": "√dhyai (pensar, contemplar)"}, {"iast": "upāsate", "sa": "उपासते", "gram": "3 pl. pres. med.", "es": "adoran", "ref": "upasana", "analisis": "upa-√ās (sentarse junto a; servir, venerar)"}], "nota": "<p><em>Tu</em>, «pero», marca el contraste con los que adoran lo imperecedero no manifiesto, de quienes Kṛṣṇa acaba de decir que su camino es más arduo (<a class=\"vref\" href=\"capitulo-12.html#v5\" data-v=\"12.5\">12.5</a>); la frase continúa en el verso siguiente. «Depositar en mí todas las acciones» repite la fórmula de <a class=\"vref\" href=\"capitulo-03.html#v30\" data-v=\"3.30\">3.30</a>. <em>Ananya</em>, «no otro», es el adjetivo que acompaña a la devoción en toda esta parte de la Gītā (<a class=\"vref\" href=\"capitulo-08.html#v14\" data-v=\"8.14\">8.14</a>, <a class=\"vref\" href=\"capitulo-09.html#v22\" data-v=\"9.22\">9.22</a>, <a class=\"vref\" href=\"capitulo-11.html#v54\" data-v=\"11.54\">11.54</a>): <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo explica como una concentración que no tiene otro apoyo que él; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, como un yoga en que no hay otro a quien adorar, es decir, una devoción exclusiva. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> une las dos glosas.</p>", "interp": [{"titulo": "Una adoración que ya es la meta", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende «todas las acciones» en el sentido más amplio: las de la vida corriente, como comer, que sirven para sostener el cuerpo, y las védicas, como el sacrificio, el don, la ofrenda al fuego y la austeridad. <em>Mat-parāḥ</em> son los que no tienen otra meta que alcanzarlo a él. Y el «yoga que no se dirige a otro» lo describe con una serie de actos: la meditación, el culto, las postraciones, las alabanzas y el canto de sus nombres, hechos porque son en sí mismos lo más querido, iguales a la meta misma. La devoción, en esta lectura, no es sólo un medio: ya tiene el sabor de lo que se busca.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "La adoración de la forma universal", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, el «yoga» de este verso es una concentración (<em>samādhi</em>) que no tiene otro apoyo que «el dios de la forma universal»: en los versos siguientes glosa también el «mí» de Kṛṣṇa como el Señor en su <a class=\"t\" href=\"glosario.html#visvarupa\" data-t=\"visvarupa\">forma universal</a>, distinto de lo imperecedero de <a class=\"vref\" href=\"capitulo-12.html#v3\" data-v=\"12.3\">12.3</a>. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> da al pasaje un desenlace propio: los que adoran así al brahman con atributos llegan, por la gracia del Señor, al mismo fruto que el conocimiento del brahman sin atributos, sin el esfuerzo de estudiarlo, reflexionarlo y meditarlo una y otra vez; ese conocimiento surge en ellos por sí solo en el <a class=\"t\" href=\"glosario.html#brahmaloka\" data-t=\"brahmaloka\">mundo de Brahmā</a>, al término de sus goces, como enseña la <em>Praśna Upaniṣad</em> (5.5); pero al glosar «sin tardanza» en <a class=\"vref\" href=\"capitulo-12.html#v7\" data-v=\"12.7\">12.7</a> dice «pronto, en este mismo nacimiento».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Sin fatiga", "html": "<p><a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> lee juntos este verso y el siguiente como la respuesta a <a class=\"vref\" href=\"capitulo-12.html#v5\" data-v=\"12.5\">12.5</a>: para los devotos que lo adoran no hay fatiga alguna (<em>kleśa</em>). Lo apoya con un pasaje del <em>Mokṣadharma</em> del <a class=\"t\" href=\"glosario.html#mahabharata\" data-t=\"mahabharata\">Mahābhārata</a> (12.328.30 en la edición crítica), en que Kṛṣṇa dice a Arjuna que, de sus cuatro clases de devotos, los mejores son los de devoción exclusiva, los que no tienen otro dios: él solo es la meta de los que obran sin buscar recompensa.</p>", "trad": "dvaita", "tradNombre": "Dvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-que-rescata"}, {"n": 7, "hablante": "krsna", "sa": ["तेषामहं समुद्धर्ता मृत्युसंसारसागरात् ।", "भवामि नचिरात्पार्थ मय्यावेशितचेतसाम् ॥७॥"], "iast": ["teṣām ahaṃ samuddhartā mṛtyu-saṃsāra-sāgarāt", "bhavāmi na cirāt pārtha mayy āveśita-cetasām"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">a esos, que tienen el pensamiento absorto en mí, yo los saco sin tardanza del océano del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a>, sujeto a la muerte, oh <a class=\"t\" href=\"glosario.html#partha\" data-t=\"partha\">Pārtha</a>.</span>", "palabras": [{"iast": "teṣām", "sa": "तेषाम्", "gram": "gen. pl. m. pron.", "es": "de esos"}, {"iast": "aham", "sa": "अहम्", "gram": "nom. sg. pron.", "es": "yo"}, {"iast": "samuddhartā", "sa": "समुद्धर्ता", "gram": "nom. sg. m.", "es": "el que saca, el que rescata", "analisis": "sam-ud-√hṛ (sacar, levantar): nombre de agente"}, {"iast": "mṛtyu-saṃsāra-sāgarāt", "sa": "मृत्युसंसारसागरात्", "gram": "abl. sg. m.", "es": "del océano del saṃsāra sujeto a la muerte", "ref": "samsara", "analisis": "mṛtyu (muerte) + saṃsāra (el ciclo de los nacimientos) + sāgara (océano)"}, {"iast": "bhavāmi", "sa": "भवामि", "gram": "1 sg. pres. act.", "es": "soy, me hago", "analisis": "√bhū (ser, llegar a ser)"}, {"iast": "na cirāt", "sa": "नचिरात्", "gram": "adv.", "es": "sin tardanza", "analisis": "na (no) + cirāt (tras largo tiempo)"}, {"iast": "pārtha", "sa": "पार्थ", "gram": "voc. sg. m.", "es": "oh Pārtha", "ref": "partha"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "āveśita-cetasām", "sa": "आवेशितचेतसाम्", "gram": "gen. pl. m. adj.", "es": "cuyo pensamiento ha entrado en mí, absortos", "analisis": "āveśita (hecho entrar), caus. de ā-√viś (entrar) + cetas (pensamiento)"}], "nota": "<p>Termina la frase empezada en <a class=\"vref\" href=\"capitulo-12.html#v6\" data-v=\"12.6\">12.6</a>. <em>Samuddhartā</em> es «el que saca», como se saca a alguien del agua: en <a class=\"vref\" href=\"capitulo-04.html#v36\" data-v=\"4.36\">4.36</a> era la barca del conocimiento la que permitía atravesar todo el mal; aquí no es un medio, sino Kṛṣṇa mismo, el que rescata, y <em>na cirāt</em>, «sin tardanza», responde a la dificultad del otro camino (<a class=\"vref\" href=\"capitulo-12.html#v5\" data-v=\"12.5\">12.5</a>). <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> precisa que los rescata «pronto», y explica que el saṃsāra es un océano porque es difícil de cruzar; lo mismo dice <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>.</p>", "interp": [{"titulo": "Los que dependen del Señor", "html": "<p>Al final de su comentario a <a class=\"vref\" href=\"capitulo-12.html#v12\" data-v=\"12.12\">12.12</a>, <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> vuelve sobre este verso para distinguir los dos caminos. De los que adoran lo imperecedero, Kṛṣṇa dijo que «llegan a mí» (<a class=\"vref\" href=\"capitulo-12.html#v4\" data-v=\"12.4\">12.4</a>), es decir, que alcanzan por sí mismos la liberación; de estos otros dice «yo los saco», lo que muestra que dependen del Señor. No podría decirse de los primeros, porque si ven que no son distintos de él ya son lo imperecedero mismo, y hablar de rescatarlos estaría fuera de lugar.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Pronto", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> glosa <em>na cirāt</em> como «en muy poco tiempo» (<em>acireṇa eva kālena</em>), y al comentar <a class=\"vref\" href=\"capitulo-12.html#v8\" data-v=\"12.8\">12.8</a> da por eso tres razones para fijar la mente en él: es la meta más alta, es fácil de alcanzar y se alcanza pronto.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "a esos, que tienen el pensamiento absorto en mí, yo los saco sin tardanza del océano del saṃsāra, que es la muerte, oh Pārtha.", "nota": "<p>El compuesto <em>mṛtyu-saṃsāra-sāgara</em> puede entenderse como «el saṃsāra acompañado de la muerte», así <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, o como «el saṃsāra, que es la muerte»: <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo llama así porque impide alcanzar al Señor.</p>"}], "ens": "el-que-rescata"}, {"n": 8, "hablante": "krsna", "sa": ["मय्येव मन आधत्स्व मयि बुद्धिं निवेशय ।", "निवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः ॥८॥"], "iast": ["mayy eva mana ādhatsva mayi buddhiṃ niveśaya", "nivasiṣyasi mayy eva ata ūrdhvaṃ na saṃśayaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pon la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> sólo en mí, asienta en mí el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a>, y después habitarás en mí, no lo dudes.</span>", "palabras": [{"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "sólo"}, {"iast": "manaḥ", "sa": "मनः", "gram": "ac. sg. n.", "es": "la mente", "ref": "manas"}, {"iast": "ādhatsva", "sa": "आधत्स्व", "gram": "2 sg. imper. med.", "es": "pon, fija", "analisis": "ā-√dhā (poner, colocar)"}, {"iast": "buddhim", "sa": "बुद्धिम्", "gram": "ac. sg. f.", "es": "el entendimiento", "ref": "buddhi"}, {"iast": "niveśaya", "sa": "निवेशय", "gram": "2 sg. imper. caus.", "es": "haz entrar, asienta", "analisis": "caus. de ni-√viś (entrar, establecerse)"}, {"iast": "nivasiṣyasi", "sa": "निवसिष्यसि", "gram": "2 sg. fut. act.", "es": "habitarás", "analisis": "ni-√vas (habitar, morar)"}, {"iast": "ata ūrdhvam", "sa": "अत ऊर्ध्वम्", "gram": "adv.", "es": "después de esto", "analisis": "ataḥ (de aquí) + ūrdhvam (más arriba, después)"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "saṃśayaḥ", "sa": "संशयः", "gram": "nom. sg. m.", "es": "duda", "analisis": "sam-√śī (yacer a un lado y a otro: vacilar)"}], "nota": "<p>Empieza aquí una escala de caminos, cada uno para quien no puede seguir el anterior (<a class=\"vref\" href=\"capitulo-12.html#v8\" data-v=\"12.8\">12.8</a>–<a class=\"vref\" href=\"capitulo-12.html#v11\" data-v=\"12.11\">12.11</a>); el primero es el más alto: la mente y el entendimiento entregados por entero, como en <a class=\"vref\" href=\"capitulo-08.html#v7\" data-v=\"8.7\">8.7</a>. El verso juega con dos verbos que suenan parecido y tienen raíces distintas: <em>niveśaya</em>, «haz que entre, asienta» (de √<em>viś</em>, «entrar»), y <em>nivasiṣyasi</em>, «habitarás» (de √<em>vas</em>, «morar»): quien hace entrar el entendimiento en Kṛṣṇa acaba morando en él. En <em>mayy eva ata</em> falta la fusión de las vocales que pediría la gramática; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> observa que es para completar el verso.</p><p><em>Ata ūrdhvam</em>, «después de esto», se entiende de dos maneras. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y Madhusūdana lo refieren a la muerte: tras la caída del cuerpo, quien así vivió morará en Kṛṣṇa, como uno con él. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, en cambio, lo lee como «en cuanto lo hayas hecho»: inmediatamente después de fijar en él la mente, ya se habita en él.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "escala-de-caminos"}, {"n": 9, "hablante": "krsna", "sa": ["अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम् ।", "अभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय ॥९॥"], "iast": ["atha cittaṃ samādhātuṃ na śaknoṣi mayi sthiram", "abhyāsa-yogena tato mām icchāptuṃ dhanañjaya"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y si no puedes fijar en mí el <a class=\"t\" href=\"glosario.html#citta\" data-t=\"citta\">pensamiento</a> con firmeza, procura entonces alcanzarme con el yoga de la <a class=\"t\" href=\"glosario.html#abhyasa\" data-t=\"abhyasa\">práctica</a>, oh <a class=\"t\" href=\"glosario.html#dhananjaya\" data-t=\"dhananjaya\">Dhanañjaya</a>.</span>", "palabras": [{"iast": "atha", "sa": "अथ", "gram": "conj.", "es": "y si"}, {"iast": "cittam", "sa": "चित्तम्", "gram": "ac. sg. n.", "es": "el pensamiento", "ref": "citta"}, {"iast": "samādhātum", "sa": "समाधातुम्", "gram": "inf.", "es": "fijar, concentrar", "analisis": "sam-ā-√dhā (poner junto, concentrar)"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "śaknoṣi", "sa": "शक्नोषि", "gram": "2 sg. pres. act.", "es": "puedes", "analisis": "√śak (poder)"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "sthiram", "sa": "स्थिरम्", "gram": "ac. sg. n. adj.", "es": "firme, con firmeza"}, {"iast": "abhyāsa-yogena", "sa": "अभ्यासयोगेन", "gram": "instr. sg. m.", "es": "con el yoga de la práctica", "ref": "abhyasa", "analisis": "abhyāsa (práctica, repetición) + yoga"}, {"iast": "tataḥ", "sa": "ततः", "gram": "adv.", "es": "entonces"}, {"iast": "mām", "sa": "माम्", "gram": "ac. sg. pron.", "es": "a mí"}, {"iast": "iccha", "sa": "इच्छ", "gram": "2 sg. imper. act.", "es": "procura, desea", "analisis": "√iṣ (desear)"}, {"iast": "āptum", "sa": "आप्तुम्", "gram": "inf.", "es": "alcanzar", "analisis": "√āp (alcanzar)"}, {"iast": "dhanañjaya", "sa": "धनञ्जय", "gram": "voc. sg. m.", "es": "oh Dhanañjaya", "ref": "dhananjaya"}], "nota": "<p>El segundo escalón: quien no logra mantener la mente en Kṛṣṇa de una vez ha de volver a ella una y otra vez. El <em>abhyāsa-yoga</em> ya apareció en <a class=\"vref\" href=\"capitulo-08.html#v8\" data-v=\"8.8\">8.8</a>, y la práctica, junto al desapego, es el medio para dominar la mente que se da en <a class=\"vref\" href=\"capitulo-06.html#v35\" data-v=\"6.35\">6.35</a>. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> define la práctica como el retirar la mente de todas partes para fijarla una y otra vez en un solo apoyo; <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, como el traer de vuelta la mente dispersa y recordarlo a él. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> repite la definición de Śaṅkara, pero precisa que el apoyo es exterior, una imagen sagrada u otro semejante, y ve intención en el vocativo: como Dhanañjaya, «el que gana riquezas», venció a muchos enemigos para obtener riquezas, así vencerá a ese enemigo que es la mente y obtendrá la riqueza del conocimiento.</p>", "interp": [{"titulo": "La práctica del recuerdo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, la práctica de este verso es la del recuerdo (<em>smṛti</em>): recordar al Señor con un amor sin medida, como un océano de cualidades benditas —belleza, bondad, compasión, dulzura, generosidad, poder, omnisciencia y otras sin número—, hasta que la mente, en lugar de fijarse en él de golpe, se asienta en él con firmeza.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "escala-de-caminos"}, {"n": 10, "hablante": "krsna", "sa": ["अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव ।", "मदर्थमपि कर्माणि कुर्वन्सिद्धिमवाप्स्यसि ॥१०॥"], "iast": ["abhyāse 'py asamartho 'si mat-karma-paramo bhava", "mad-artham api karmāṇi kurvan siddhim avāpsyasi"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Si tampoco eres capaz de la práctica, dedícate por entero a mis obras: aun haciendo las <a class=\"t\" href=\"glosario.html#karma\" data-t=\"karma\">acciones</a> por mí alcanzarás la perfección.</span>", "palabras": [{"iast": "abhyāse", "sa": "अभ्यासे", "gram": "loc. sg. m.", "es": "en la práctica, para la práctica", "ref": "abhyasa"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "ni siquiera, tampoco"}, {"iast": "asamarthaḥ", "sa": "असमर्थः", "gram": "nom. sg. m. adj.", "es": "incapaz", "analisis": "a (no) + samartha (capaz)"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "eres", "analisis": "√as (ser)"}, {"iast": "mat-karma-paramaḥ", "sa": "मत्कर्मपरमः", "gram": "nom. sg. m. adj.", "es": "que tiene mis obras por lo supremo", "ref": "karma", "analisis": "mad (yo) + karman (obra) + parama (supremo)"}, {"iast": "bhava", "sa": "भव", "gram": "2 sg. imper. act.", "es": "sé", "analisis": "√bhū (ser)"}, {"iast": "mad-artham", "sa": "मदर्थम्", "gram": "adv.", "es": "por mí, para mí", "analisis": "mad (yo) + artha (fin)"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "aun, incluso"}, {"iast": "karmāṇi", "sa": "कर्माणि", "gram": "ac. pl. n.", "es": "las acciones", "ref": "karma"}, {"iast": "kurvan", "sa": "कुर्वन्", "gram": "nom. sg. m. part. pres.", "es": "haciendo", "analisis": "√kṛ (hacer)"}, {"iast": "siddhim", "sa": "सिद्धिम्", "gram": "ac. sg. f.", "es": "la perfección, la consumación", "analisis": "√sidh (lograrse, cumplirse)"}, {"iast": "avāpsyasi", "sa": "अवाप्स्यसि", "gram": "2 sg. fut. act.", "es": "alcanzarás", "analisis": "ava-√āp (alcanzar)"}], "nota": "<p>El tercer escalón: no la mente fija, sino las manos ocupadas en lo que es para él. <em>Mat-karma-parama</em> es literalmente «el que tiene mis obras por lo supremo»; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa como «aquel para quien lo principal son las acciones hechas para mí». Compárese con «quien hace mis obras» de <a class=\"vref\" href=\"capitulo-11.html#v55\" data-v=\"11.55\">11.55</a>. El <em>api</em> de la segunda línea, «aun», dice que también este camino, que no exige concentración, lleva a la meta. Para Śaṅkara y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, esa «perfección» llega por grados: la acción purifica la mente, y la mente purificada alcanza el conocimiento.</p>", "interp": [{"titulo": "Las obras del templo", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> enumera cuáles son «mis obras»: construir templos y plantar jardines para el Señor, encender lámparas, barrer, rociar y untar el suelo del templo, recoger flores, el culto, el canto de sus nombres, dar vueltas en torno a él, postrarse y alabarlo, todo hecho por amor. Haciéndolas, dice, se llega pronto a la mente firme en él que pedía el escalón anterior, y con ella a la perfección, que es alcanzarlo.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Los actos de devoción", "html": "<p><a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> da otros ejemplos: los ayunos del undécimo día lunar (<em>ekādaśī</em>), los votos y el canto de los nombres; la perfección es la liberación. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> piensa en los actos del <em>bhāgavata-dharma</em>, como escuchar y cantar sus glorias, y ve la perfección en llegar a ser brahman, tras la purificación de la mente y el nacimiento del conocimiento.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "escala-de-caminos"}, {"n": 11, "hablante": "krsna", "sa": ["अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः ।", "सर्वकर्मफलत्यागं ततः कुरु यतात्मवान् ॥११॥"], "iast": ["athaitad apy aśakto 'si kartuṃ mad-yogam āśritaḥ", "sarva-karma-phala-tyāgaṃ tataḥ kuru yatātmavān"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Y si ni siquiera eres capaz de hacer esto, acógete a mi yoga y, con la mente dominada, <a class=\"t\" href=\"glosario.html#tyaga\" data-t=\"tyaga\">abandona</a> entonces el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de todas tus acciones.</span>", "palabras": [{"iast": "atha", "sa": "अथ", "gram": "conj.", "es": "y si"}, {"iast": "etat", "sa": "एतत्", "gram": "ac. sg. n. pron.", "es": "esto"}, {"iast": "api", "sa": "अपि", "gram": "part.", "es": "ni siquiera"}, {"iast": "aśaktaḥ", "sa": "अशक्तः", "gram": "nom. sg. m. adj.", "es": "incapaz", "analisis": "a (no) + śakta (capaz), √śak (poder)"}, {"iast": "asi", "sa": "असि", "gram": "2 sg. pres.", "es": "eres"}, {"iast": "kartum", "sa": "कर्तुम्", "gram": "inf.", "es": "de hacer", "analisis": "√kṛ (hacer)"}, {"iast": "mad-yogam", "sa": "मद्योगम्", "gram": "ac. sg. m.", "es": "mi yoga", "ref": "yoga", "analisis": "mad (yo) + yoga"}, {"iast": "āśritaḥ", "sa": "आश्रितः", "gram": "nom. sg. m. part. pas.", "es": "acogido a, refugiado en", "analisis": "ā-√śri (apoyarse, acogerse)"}, {"iast": "sarva-karma-phala-tyāgam", "sa": "सर्वकर्मफलत्यागम्", "gram": "ac. sg. m.", "es": "el abandono del fruto de todas las acciones", "ref": "tyaga", "analisis": "sarva (todo) + karman (acción) + phala (fruto) + tyāga (abandono), √tyaj (dejar)"}, {"iast": "tataḥ", "sa": "ततः", "gram": "adv.", "es": "entonces"}, {"iast": "kuru", "sa": "कुरु", "gram": "2 sg. imper. act.", "es": "haz", "analisis": "√kṛ (hacer)"}, {"iast": "yatātmavān", "sa": "यतात्मवान्", "gram": "nom. sg. m. adj.", "es": "con la mente dominada, dueño de sí", "analisis": "yata (refrenado), de √yam + ātmavat (que tiene un sí-mismo, dueño de sí)"}], "nota": "<p>El último escalón, para quien no puede ni siquiera dedicar sus obras a Kṛṣṇa: seguir actuando, pero dejar el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a>. Es la enseñanza que abre la Gītā (<a class=\"vref\" href=\"capitulo-02.html#v47\" data-v=\"2.47\">2.47</a>–<a class=\"vref\" href=\"capitulo-02.html#v48\" data-v=\"2.48\">2.48</a>) y que el capítulo 18 dará como definición del verdadero <a class=\"t\" href=\"glosario.html#tyaga\" data-t=\"tyaga\">abandono</a> (<a class=\"vref\" href=\"capitulo-18.html#v2\" data-v=\"18.2\">18.2</a>, <a class=\"vref\" href=\"capitulo-18.html#v11\" data-v=\"18.11\">18.11</a>). <em>Yatātmavān</em> reúne «refrenado» y «dueño de sí»; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo separa en dos cualidades: con los sentidos dominados y con discernimiento.</p>", "interp": [{"titulo": "Dejar el fruto en manos del Señor", "html": "<p><a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> explica en qué consiste este abandono con palabras del que lo practica: «Yo he de hacer las acciones como pueda, por mandato del Señor; su fruto, visible o invisible, depende del Señor». Así se deja la carga en él, se suelta el apego al fruto, y por su gracia se alcanza el fin.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La escalera al revés", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el abandono del fruto no es el último recurso de un camino que se degrada, sino el primer peldaño de una subida: con las acciones hechas sin buscar su fruto, como culto al Señor, se destruyen las faltas y se obtiene el conocimiento del sí-mismo; visto directamente el sí-mismo como perteneciente sólo al Señor, nace por sí misma la devoción suprema. Lo confirma con <a class=\"vref\" href=\"capitulo-18.html#v46\" data-v=\"18.46\">18.46</a> y <a class=\"vref\" href=\"capitulo-18.html#v54\" data-v=\"18.54\">18.54</a>: quien adora al Señor con su propia tarea alcanza la perfección y, convertido en brahman, obtiene «la devoción suprema a mí».</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Y si, acogido a mi yoga, no eres capaz siquiera de hacer esto, abandona entonces, con la mente dominada, el fruto de todas las acciones.", "nota": "<p>Depende de con qué se construya <em>mad-yogam āśritaḥ</em>, «acogido a mi yoga». <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo unen al abandono del fruto, como la traducción principal: para Śaṅkara, ese yoga consiste en hacer las acciones depositándolas en Kṛṣṇa; para Śrīdhara, en tenerlo a él por único refugio; Madhusūdana admite las dos explicaciones. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo une a la incapacidad: si, apoyado en el yoga de la devoción, no se puede hacer siquiera lo que forma parte de él, hay que pasar a otro camino, el de la contemplación del propio sí-mismo, que enseñan los seis primeros capítulos, y abandonar el fruto como medio para él.</p>"}], "ens": "escala-de-caminos"}, {"n": 12, "hablante": "krsna", "sa": ["श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते ।", "ध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम् ॥१२॥"], "iast": ["śreyo hi jñānam abhyāsāj jñānād dhyānaṃ viśiṣyate", "dhyānāt karma-phala-tyāgas tyāgāc chāntir anantaram"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Mejor es, en verdad, el <a class=\"t\" href=\"glosario.html#jnana\" data-t=\"jnana\">conocimiento</a> que la <a class=\"t\" href=\"glosario.html#abhyasa\" data-t=\"abhyasa\">práctica</a>; más que el conocimiento vale la <a class=\"t\" href=\"glosario.html#dhyana\" data-t=\"dhyana\">meditación</a>, y más que la meditación, el <a class=\"t\" href=\"glosario.html#tyaga\" data-t=\"tyaga\">abandono</a> del fruto de las acciones: del abandono viene en seguida la <a class=\"t\" href=\"glosario.html#santi\" data-t=\"santi\">paz</a>.</span>", "palabras": [{"iast": "śreyaḥ", "sa": "श्रेयः", "gram": "nom. sg. n. comp.", "es": "mejor", "analisis": "comparativo de śrī (excelente)"}, {"iast": "hi", "sa": "हि", "gram": "part.", "es": "en verdad, pues"}, {"iast": "jñānam", "sa": "ज्ञानम्", "gram": "nom. sg. n.", "es": "el conocimiento", "ref": "jnana"}, {"iast": "abhyāsāt", "sa": "अभ्यासात्", "gram": "abl. sg. m.", "es": "que la práctica", "ref": "abhyasa"}, {"iast": "jñānāt", "sa": "ज्ञानात्", "gram": "abl. sg. n.", "es": "que el conocimiento", "ref": "jnana"}, {"iast": "dhyānam", "sa": "ध्यानम्", "gram": "nom. sg. n.", "es": "la meditación", "ref": "dhyana"}, {"iast": "viśiṣyate", "sa": "विशिष्यते", "gram": "3 sg. pres. pas.", "es": "sobresale, es superior", "analisis": "vi-√śiṣ (distinguir, sobresalir)"}, {"iast": "dhyānāt", "sa": "ध्यानात्", "gram": "abl. sg. n.", "es": "que la meditación", "ref": "dhyana"}, {"iast": "karma-phala-tyāgaḥ", "sa": "कर्मफलत्यागः", "gram": "nom. sg. m.", "es": "el abandono del fruto de las acciones", "ref": "tyaga", "analisis": "karman (acción) + phala (fruto) + tyāga (abandono)"}, {"iast": "tyāgāt", "sa": "त्यागात्", "gram": "abl. sg. m.", "es": "del abandono", "ref": "tyaga"}, {"iast": "śāntiḥ", "sa": "शान्तिः", "gram": "nom. sg. f.", "es": "la paz", "ref": "santi", "analisis": "√śam (aquietarse)"}, {"iast": "anantaram", "sa": "अनन्तरम्", "gram": "adv.", "es": "inmediatamente, sin intervalo", "analisis": "an (sin) + antara (intervalo)"}], "nota": "<p>Uno de los versos más discutidos de la Gītā. Leído al pie de la letra, invierte la escala de los versos anteriores: el abandono del fruto, propuesto en <a class=\"vref\" href=\"capitulo-12.html#v11\" data-v=\"12.11\">12.11</a> a quien no puede nada más, queda ahora por encima de la meditación y del conocimiento. Los comentaristas lo explican de maneras distintas (véanse las interpretaciones), pero coinciden en que no puede querer decir que lo más fácil sea sin más lo más alto. <em>Anantaram</em>, «sin intervalo», dice que la paz no espera: llega en cuanto se deja el fruto, como en <a class=\"vref\" href=\"capitulo-05.html#v12\" data-v=\"5.12\">5.12</a>, donde el disciplinado que abandona el fruto alcanza la paz definitiva.</p>", "interp": [{"titulo": "Un elogio para animar", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lee la escala así: mejor que una práctica hecha sin discernimiento es el conocimiento; mejor que ese conocimiento, la meditación que se apoya en él; y mejor que la meditación, el abandono del fruto. Pero esto último, dice, es un elogio (<em>stuti</em>) para animar a quien no puede hacer otra cosa, y lo justifica por un rasgo común: la <em>Kaṭha Upaniṣad</em> (6.14) enseña que cuando se sueltan todos los deseos que habitan el corazón, el mortal se vuelve inmortal; los frutos de las acciones son deseos, y quien los abandona comparte algo de aquella renuncia total. Así se alaba hoy a los brahmanes recordando que un brahmán, Agastya, se bebió el océano. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> repite la explicación y el ejemplo, y añade el de Paraśurāma, que dejó la tierra sin guerreros. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> también entiende el verso como un elogio del abandono del fruto; la superioridad de la meditación sobre el conocimiento la apoya en la <em>Muṇḍaka Upaniṣad</em> (3.1.8): «meditando, se le ve, el sin partes».</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Lo que dice Śaṅkara de todo el pasaje", "html": "<p>Al cerrar su comentario a este verso, <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> saca una conclusión sobre todo el capítulo: el camino de <a class=\"vref\" href=\"capitulo-12.html#v6\" data-v=\"12.6\">12.6</a>–<a class=\"vref\" href=\"capitulo-12.html#v11\" data-v=\"12.11\">12.11</a> —fijar la mente en el Señor de la forma universal, obrar para él— supone la distinción entre el sí-mismo y el Señor, y por eso no es para quien adora lo imperecedero viendo que no hay distinción. A partir de <a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>, dice, Kṛṣṇa pasa a describir las cualidades de estos últimos, los renunciantes que conocen lo imperecedero, como medio directo de la inmortalidad.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "Mejor para quien no puede", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> entiende «mejor» como «más conveniente para quien lo practica», y relee la escala en ese sentido. El recuerdo del Señor sin un amor intenso es áspero y difícil; para quien no puede practicarlo, es más conveniente el conocimiento directo del propio sí-mismo, y para quien aún no lo ha alcanzado, la meditación en el sí-mismo, que conduce a él; y para quien tampoco logra meditar, la acción hecha sin buscar su fruto. De ella viene la paz, de la paz la meditación, de la meditación el conocimiento, de este la visión del sí-mismo, y de esta la devoción suprema. Vedānta Deśika, su comentador, lo ilustra con varias imágenes: el niño de pecho que alza la mano para coger la luna; el muchacho que, ansioso del jugo de la fruta madura, aprieta una verde y no saca nada; y, para lo difícil que es ese recuerdo a quien no ha destruido sus faltas, el enfermo de bilis que bebe leche.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Un elogio, o el abandono unido a la meditación", "html": "<p><a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> admite que el conocimiento es mejor que una práctica hecha sin él y que la meditación acompañada de conocimiento es mejor que el solo conocimiento; pero que el abandono del fruto supere a la meditación sólo puede ser, dice, un elogio: de otro modo no se lo propondría a quien es incapaz de lo demás. Ofrece además otra lectura: lo superior a la meditación sola sería el abandono unido a la meditación, porque del puro abandono no se sigue en seguida la liberación.</p>", "trad": "dvaita", "tradNombre": "Dvaita"}, {"titulo": "El centro de la Gītā", "html": "<p><a class=\"t\" href=\"glosario.html#gandhi\" data-t=\"gandhi\">Gandhi</a>, que tituló su versión de la Gītā <em>Anāsaktiyoga</em>, «el yoga del desapego», escribió en la introducción que el remedio incomparable que enseña el poema es el abandono del fruto de la acción, y que ese es el centro en torno al cual se teje toda la Gītā.</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "escala-de-caminos"}, {"n": 13, "hablante": "krsna", "sa": ["अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च ।", "निर्ममो निरहङ्कारः समदुःखसुखः क्षमी ॥१३॥"], "iast": ["adveṣṭā sarva-bhūtānāṃ maitraḥ karuṇa eva ca", "nirmamo nirahaṅkāraḥ sama-duḥkha-sukhaḥ kṣamī"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Quien no odia a ningún ser, amistoso y compasivo, libre del «mío» y del <a class=\"t\" href=\"glosario.html#ahankara\" data-t=\"ahankara\">sentido del yo</a>, igual en el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a> y en el <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">placer</a>, paciente,</span>", "palabras": [{"iast": "adveṣṭā", "sa": "अद्वेष्टा", "gram": "nom. sg. m.", "es": "el que no odia", "analisis": "a- (no) + dveṣṭṛ (el que odia), de √dviṣ (odiar)"}, {"iast": "sarva-bhūtānām", "sa": "सर्वभूतानाम्", "gram": "gen. pl. n.", "es": "a ningún ser, a todos los seres", "analisis": "sarva (todo) + bhūta (ser)"}, {"iast": "maitraḥ", "sa": "मैत्रः", "gram": "nom. sg. m. adj.", "es": "amistoso", "analisis": "derivado de mitra (amigo) / maitrī (amistad)"}, {"iast": "karuṇaḥ", "sa": "करुणः", "gram": "nom. sg. m. adj.", "es": "compasivo", "analisis": "karuṇā (compasión)"}, {"iast": "eva", "sa": "एव", "gram": "part.", "es": "también, en verdad"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "nirmamaḥ", "sa": "निर्ममः", "gram": "nom. sg. m. adj.", "es": "libre del «mío»", "analisis": "nis- (sin) + mama (mío): sin sentido de posesión"}, {"iast": "nirahaṅkāraḥ", "sa": "निरहङ्कारः", "gram": "nom. sg. m. adj.", "es": "libre del sentido del yo", "ref": "ahankara", "analisis": "nis- (sin) + ahaṅkāra (el «yo hago»)"}, {"iast": "sama-duḥkha-sukhaḥ", "sa": "समदुःखसुखः", "gram": "nom. sg. m. adj.", "es": "igual en el dolor y en el placer", "ref": "samatva", "analisis": "sama (igual) + duḥkha (dolor) + sukha (placer)"}, {"iast": "kṣamī", "sa": "क्षमी", "gram": "nom. sg. m. adj.", "es": "paciente, que perdona", "analisis": "kṣamin, de kṣamā (paciencia, perdón), √kṣam (soportar)"}], "nota": "<p>Empieza aquí el retrato del devoto que Kṛṣṇa ama, que ocupa el resto del capítulo. La primera frase se extiende por dos versos y termina en <a class=\"vref\" href=\"capitulo-12.html#v14\" data-v=\"12.14\">12.14</a> con el estribillo «ese devoto mío me es querido», que vuelve, con pequeñas variaciones, en <a class=\"vref\" href=\"capitulo-12.html#v15\" data-v=\"12.15\">12.15</a>, <a class=\"vref\" href=\"capitulo-12.html#v16\" data-v=\"12.16\">12.16</a>, <a class=\"vref\" href=\"capitulo-12.html#v17\" data-v=\"12.17\">12.17</a> y <a class=\"vref\" href=\"capitulo-12.html#v19\" data-v=\"12.19\">12.19</a>, y una última vez, intensificado, en <a class=\"vref\" href=\"capitulo-12.html#v20\" data-v=\"12.20\">12.20</a>: seis veces en ocho versos. <em>Nirmamo nirahaṅkāraḥ</em>, «libre del “mío” y del sentido del yo», repite a la letra una expresión de <a class=\"vref\" href=\"capitulo-02.html#v71\" data-v=\"2.71\">2.71</a>; <em>sama-duḥkha-sukha</em>, «igual en el dolor y en el placer», es la de <a class=\"vref\" href=\"capitulo-02.html#v15\" data-v=\"2.15\">2.15</a>. <em>Kṣamī</em> es el que soporta y perdona: <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo explican como el que, insultado o golpeado, permanece sin alterarse; <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, como el que no se altera ante el placer y el dolor inevitables que traen los contactos de los sentidos.</p>", "interp": [{"titulo": "El renunciante que ve a todos como a sí mismo", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, los versos <a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>–<a class=\"vref\" href=\"capitulo-12.html#v19\" data-v=\"12.19\">12.19</a> describen a los que adoran lo imperecedero, de los que se habló en <a class=\"vref\" href=\"capitulo-12.html#v3\" data-v=\"12.3\">12.3</a>: renunciantes (<em>saṃnyāsin</em>) que han abandonado todo deseo y están asentados en el conocimiento de la realidad suprema. No odian a nadie, ni siquiera a lo que les causa dolor, porque ven a todos los seres como su propio sí-mismo; y el compasivo es «el que da seguridad a todos los seres», es decir, el renunciante. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> dice lo mismo: Kṛṣṇa describe, en siete versos, a los que adoran lo imperecedero, los renunciantes que no ven diferencia. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> lee el pasaje de otro modo: son las cualidades del devoto que le ganan pronto la gracia del Señor, y las enumera en ocho versos, hasta <a class=\"vref\" href=\"capitulo-12.html#v20\" data-v=\"12.20\">12.20</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "No odiar a quien hace daño", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el devoto de estos versos es el que adora a Kṛṣṇa por medio de sus obras, el <em>karma-yogin</em> de <a class=\"vref\" href=\"capitulo-12.html#v11\" data-v=\"12.11\">12.11</a>–<a class=\"vref\" href=\"capitulo-12.html#v12\" data-v=\"12.12\">12.12</a>. No odia a nadie, ni siquiera a quienes lo odian y le hacen daño, porque piensa que esos seres, movidos por el Señor, actúan así de acuerdo con las faltas de él mismo; y con ellos mismos es amistoso, y compasivo cuando sufren. Libre del sentido del yo es, para Rāmānuja, el que no toma el cuerpo por el sí-mismo. Vedānta Deśika, en su glosa, rechaza expresamente, sin nombrarlo, la explicación de Śaṅkara («el que ha perdido la noción del yo»), porque para su escuela el «yo» es el sí-mismo mismo y no puede desaparecer.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "El enemigo y las propias faltas", "html": "<p>Prabhupāda describe aquí al devoto puro y da una explicación muy cercana a la de Rāmānuja: el devoto no se vuelve enemigo de su enemigo, porque piensa: «Esta persona actúa como enemiga mía a causa de mis propias malas acciones pasadas; así que es mejor sufrir que protestar». Cita el <em>Bhāgavata Purāṇa</em> (10.14.8): quien vive esperando la compasión del Señor mientras sufre el fruto de sus propios actos.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}, {"titulo": "Amistad y compasión", "html": "<p><a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> reparte las tres primeras actitudes según a quién se dirigen: ningún odio hacia los superiores, amistad (<em>maitrī</em>) con los iguales, compasión (<em>karuṇā</em>) con los inferiores. La pareja <em>maitrī</em> y <em>karuṇā</em> aparece también en los <em>Yoga-sūtras</em> (1.33), que recomiendan cultivar la amistad, la compasión, la alegría por el bien ajeno y la ecuanimidad para serenar la mente, y es la misma serie que el budismo llama las «moradas divinas» (<em>brahma-vihāra</em>). La Gītā no las enumera como serie; las incluye en un retrato.</p>", "trad": "textual", "tradNombre": "Observaciones sobre el texto"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-devoto-que-me-es-querido"}, {"n": 14, "hablante": "krsna", "sa": ["सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः ।", "मय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः ॥१४॥"], "iast": ["santuṣṭaḥ satataṃ yogī yatātmā dṛḍha-niścayaḥ", "mayy arpita-mano-buddhir yo mad-bhaktaḥ sa me priyaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">siempre contento, <a class=\"t\" href=\"glosario.html#yogin\" data-t=\"yogin\">yogui</a>, dueño de sí, de resolución firme, con la <a class=\"t\" href=\"glosario.html#manas\" data-t=\"manas\">mente</a> y el <a class=\"t\" href=\"glosario.html#buddhi\" data-t=\"buddhi\">entendimiento</a> puestos en mí: ese <a class=\"t\" href=\"glosario.html#bhakta\" data-t=\"bhakta\">devoto</a> mío me es querido.</span>", "palabras": [{"iast": "santuṣṭaḥ", "sa": "सन्तुष्टः", "gram": "nom. sg. m. part. pas.", "es": "contento", "analisis": "sam-√tuṣ (estar satisfecho)"}, {"iast": "satatam", "sa": "सततम्", "gram": "adv.", "es": "siempre"}, {"iast": "yogī", "sa": "योगी", "gram": "nom. sg. m.", "es": "yogui", "ref": "yogin"}, {"iast": "yatātmā", "sa": "यतात्मा", "gram": "nom. sg. m. adj.", "es": "dueño de sí", "ref": "atman", "analisis": "yata (dominado) + ātman (uno mismo)"}, {"iast": "dṛḍha-niścayaḥ", "sa": "दृढनिश्चयः", "gram": "nom. sg. m. adj.", "es": "de resolución firme", "analisis": "dṛḍha (firme) + niścaya (resolución, convicción)"}, {"iast": "mayi", "sa": "मयि", "gram": "loc. sg. pron.", "es": "en mí"}, {"iast": "arpita-mano-buddhiḥ", "sa": "अर्पितमनोबुद्धिः", "gram": "nom. sg. m. adj.", "es": "con la mente y el entendimiento puestos", "ref": "buddhi", "analisis": "arpita (puesto, ofrecido, de caus. √ṛ) + manas (mente) + buddhi (entendimiento)"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "mad-bhaktaḥ", "sa": "मद्भक्तः", "gram": "nom. sg. m.", "es": "mi devoto", "ref": "bhakta", "analisis": "mad (yo) + bhakta (devoto)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "me, para mí"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m. adj.", "es": "querido"}], "nota": "<p><em>Satatam</em>, «siempre», puede ir con «contento» (<a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>) o con «yogui» (<a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>); <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo une a los dos; <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo extiende a todo el verso. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> ve en este retrato el desarrollo de lo que se anunció en <a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a>: «yo le soy sobremanera querido al sabio, y él me es querido a mí». <em>Me priyaḥ</em>, «me es querido», es lo contrario de lo que Kṛṣṇa dijo en <a class=\"vref\" href=\"capitulo-09.html#v29\" data-v=\"9.29\">9.29</a>, «no hay nadie a quien prefiera»: el mismo verso añadía que los que lo adoran con devoción están en él.</p>", "interp": [{"titulo": "La firme convicción", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> entiende <em>dṛḍha-niścaya</em> como la convicción firme acerca de la realidad del sí-mismo, y «con la mente y el entendimiento puestos en mí» como el renunciante que los ha fijado sólo en Kṛṣṇa. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo precisa: la convicción «yo soy brahman, que no actúa ni goza, ser, conciencia y dicha sin segundo», firme porque los malos razonadores no pueden quebrantarla; es, dice, el <a class=\"t\" href=\"glosario.html#sthitaprajna\" data-t=\"sthitaprajna\">de sabiduría firme</a> del capítulo 2. Y el devoto, para él, es el que conoce el brahman imperecedero puro.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "La mente puesta en el Señor que se adora con las obras", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el devoto pone en Kṛṣṇa la mente y el entendimiento pensando: «Sólo al Señor Vāsudeva se le adora con las obras hechas sin buscar su fruto, y, adorado así, él me concederá la visión directa del sí-mismo». La convicción firme es la que se tiene sobre lo que enseñan las escrituras acerca del sí-mismo, y «siempre yogui», el que medita sin cesar en el sí-mismo separado de la naturaleza. <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, en cambio, lee <em>dṛḍha-niścaya</em> como la convicción firme que tiene por objeto a Kṛṣṇa.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-devoto-que-me-es-querido"}, {"n": 15, "hablante": "krsna", "sa": ["यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः ।", "हर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः ॥१५॥"], "iast": ["yasmān nodvijate loko lokān nodvijate ca yaḥ", "harṣāmarṣa-bhayodvegair mukto yaḥ sa ca me priyaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Aquel que no inquieta a la gente y a quien la gente no inquieta, libre de la euforia, la impaciencia, el miedo y la inquietud, ése también me es querido.</span>", "palabras": [{"iast": "yasmāt", "sa": "यस्मात्", "gram": "abl. sg. m. rel.", "es": "ante quien, por causa de quien"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "udvijate", "sa": "उद्विजते", "gram": "3 sg. pres. med.", "es": "se inquieta, se sobresalta", "analisis": "ud-√vij (estremecerse, apartarse con temor)"}, {"iast": "lokaḥ", "sa": "लोकः", "gram": "nom. sg. m.", "es": "la gente, el mundo"}, {"iast": "lokāt", "sa": "लोकात्", "gram": "abl. sg. m.", "es": "ante la gente"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "harṣāmarṣa-bhayodvegaiḥ", "sa": "हर्षामर्षभयोद्वेगैः", "gram": "instr. pl. m.", "es": "de la euforia, la impaciencia, el miedo y la inquietud", "analisis": "harṣa (euforia, alegría excitada) + amarṣa (impaciencia, intolerancia) + bhaya (miedo) + udvega (inquietud, de ud-√vij)"}, {"iast": "muktaḥ", "sa": "मुक्तः", "gram": "nom. sg. m. part. pas.", "es": "libre", "analisis": "√muc (soltar)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "me"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m. adj.", "es": "querido"}], "nota": "<p>El verso juega con una sola raíz, <em>ud-√vij</em>, «estremecerse, apartarse con temor»: el devoto no hace que la gente se sobresalte, ni se sobresalta ante ella, y está libre de <em>udvega</em>, la inquietud. La traducción conserva el juego con «inquietar» e «inquietud». <em>Harṣa</em> no es la alegría serena, sino la excitación del que consigue lo que quería; <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> la describen por sus señales: se eriza el vello, saltan las lágrimas. <a class=\"vref\" href=\"capitulo-05.html#v20\" data-v=\"5.20\">5.20</a> daba ya la misma pareja: el que conoce brahman «no se exalta al obtener lo agradable ni se turba (<em>na udvijet</em>) al recibir lo desagradable».</p>", "interp": [{"titulo": "Los que no dejan en paz", "html": "<p><a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> ven en el que no inquieta a nadie al renunciante, que «da seguridad a todos los seres». Madhusūdana da a los dos lados del verso un contenido concreto. La gente que podría inquietarlo son los malvados cuyo único voto es molestar a los inocentes; y el devoto no se inquieta ante ellos porque no ve dualidad y es paciente. La inquietud (<em>udvega</em>) es la del renunciante que piensa: «solo, en un lugar desierto, sin nada, ¿cómo voy a vivir?». No ha tenido que esforzarse por echar de sí estas emociones: se han ido solas, porque ya no encuentran sitio en él.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "Aquel que no inquieta a la gente y a quien la gente no inquieta, libre de la euforia, la envidia, el miedo y la inquietud, ése también me es querido.", "nota": "<p><em>Amarṣa</em> es, en general, no soportar algo: la impaciencia, la indignación. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> lo glosa así, «intolerancia». <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> precisan qué es lo que no se soporta: la ganancia o la superioridad de otro. De ahí «envidia».</p>"}], "ens": "el-devoto-que-me-es-querido"}, {"n": 16, "hablante": "krsna", "sa": ["अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः ।", "सर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः ॥१६॥"], "iast": ["anapekṣaḥ śucir dakṣa udāsīno gata-vyathaḥ", "sarvārambha-parityāgī yo mad-bhaktaḥ sa me priyaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El que no espera nada, puro, diestro, <a class=\"t\" href=\"glosario.html#udasina\" data-t=\"udasina\">imparcial</a>, libre de angustia, que ha abandonado toda empresa: ese <a class=\"t\" href=\"glosario.html#bhakta\" data-t=\"bhakta\">devoto</a> mío me es querido.</span>", "palabras": [{"iast": "anapekṣaḥ", "sa": "अनपेक्षः", "gram": "nom. sg. m. adj.", "es": "que no espera nada", "analisis": "an- (no) + apekṣā (expectativa, dependencia), apa-√īkṣ (mirar hacia)"}, {"iast": "śuciḥ", "sa": "शुचिः", "gram": "nom. sg. m. adj.", "es": "puro"}, {"iast": "dakṣaḥ", "sa": "दक्षः", "gram": "nom. sg. m. adj.", "es": "diestro, hábil"}, {"iast": "udāsīnaḥ", "sa": "उदासीनः", "gram": "nom. sg. m. adj.", "es": "imparcial, que se mantiene al margen", "ref": "udasina", "analisis": "ud (aparte) + āsīna (sentado), √ās"}, {"iast": "gata-vyathaḥ", "sa": "गतव्यथः", "gram": "nom. sg. m. adj.", "es": "libre de angustia", "analisis": "gata (ido) + vyathā (angustia, temblor)"}, {"iast": "sarvārambha-parityāgī", "sa": "सर्वारम्भपरित्यागी", "gram": "nom. sg. m. adj.", "es": "que ha abandonado toda empresa", "ref": "tyaga", "analisis": "sarva (todo) + ārambha (empresa, lo que se emprende) + parityāgin (que abandona); el sufijo -in indica hábito"}, {"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "quien"}, {"iast": "mad-bhaktaḥ", "sa": "मद्भक्तः", "gram": "nom. sg. m.", "es": "mi devoto", "ref": "bhakta"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "me"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m. adj.", "es": "querido"}], "nota": "<p><em>Ārambha</em> es lo que se emprende, la empresa; ya en <a class=\"vref\" href=\"capitulo-04.html#v19\" data-v=\"4.19\">4.19</a> el sabio era aquel cuyas empresas están libres del deseo. <em>Sarvārambha-parityāgī</em>, «que ha abandonado toda empresa», volverá a la letra en <a class=\"vref\" href=\"capitulo-14.html#v25\" data-v=\"14.25\">14.25</a>, entre los rasgos del que ha ido más allá de las tres guṇas. Los comentaristas no lo entienden como dejar de actuar. Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, las empresas abandonadas son las acciones movidas por el deseo de un fruto en este mundo o en el otro; para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, todas salvo las que mandan las escrituras. <em>Dakṣa</em>, «diestro», es para Śaṅkara y Madhusūdana el que comprende al instante y como es debido lo que hay que hacer; para Śrīdhara, el que no es perezoso. <em>Gata-vyatha</em>, «libre de angustia», lo glosa Śaṅkara como «libre de miedo»; Śrīdhara, como libre de aflicción del ánimo, y Madhusūdana, como el que no siente dolor aunque lo golpeen.</p>", "interp": [{"titulo": "Gandhi: no hacer planes de expansión", "html": "<p>Gandhi, que pedía a las parejas que se casaban en su <em>āśram</em> aprender de memoria este capítulo, explicó así el abandono de toda empresa en una carta de 1930: el devoto no hace planes de expansión. Si un comerciante de telas piensa vender también leña, o si, con una tienda, piensa abrir cinco más, eso es <em>ārambha</em>; y lo mismo vale para el servicio a la nación: quien trabaja hoy en el <em>khādī</em> no se pasará mañana a la cría de vacas, pasado mañana a la agricultura y al cuarto día a la asistencia médica. «El devoto no deja de trabajar; de hecho, no es nada si no es un trabajador. Sólo deja de tener pensamientos innecesarios sobre su trabajo». Lo contrario, añade, es lo que dice el demoníaco en <a class=\"vref\" href=\"capitulo-16.html#v13\" data-v=\"16.13\">16.13</a>: «esto lo he conseguido hoy; aquel deseo lo cumpliré mañana».</p>", "trad": "moderna", "tradNombre": "Lecturas modernas"}, {"titulo": "Puro y diestro para el rito", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lee los adjetivos del verso en relación con la acción prescrita: puro es el que ha nutrido su cuerpo con alimentos que las escrituras permiten; diestro, el que es capaz de emprender las acciones que ellas mandan, e imparcial respecto de todo lo demás; libre de angustia, el que no sufre por el frío, el calor o la aspereza inevitables al cumplirlas. Lo que abandona son las empresas ajenas a las escrituras.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-devoto-que-me-es-querido"}, {"n": 17, "hablante": "krsna", "sa": ["यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति ।", "शुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः ॥१७॥"], "iast": ["yo na hṛṣyati na dveṣṭi na śocati na kāṅkṣati", "śubhāśubha-parityāgī bhaktimān yaḥ sa me priyaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">El que no se alegra ni odia, no se aflige ni desea, que ha abandonado lo bueno y lo malo, lleno de <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>: ése me es querido.</span>", "palabras": [{"iast": "yaḥ", "sa": "यः", "gram": "nom. sg. m. rel.", "es": "el que"}, {"iast": "na", "sa": "न", "gram": "part.", "es": "no"}, {"iast": "hṛṣyati", "sa": "हृष्यति", "gram": "3 sg. pres. act.", "es": "se alegra, se exalta", "analisis": "√hṛṣ (alegrarse, erizarse)"}, {"iast": "dveṣṭi", "sa": "द्वेष्टि", "gram": "3 sg. pres. act.", "es": "odia", "ref": "raga-dvesa", "analisis": "√dviṣ (odiar)"}, {"iast": "śocati", "sa": "शोचति", "gram": "3 sg. pres. act.", "es": "se aflige", "ref": "soka", "analisis": "√śuc (afligirse)"}, {"iast": "kāṅkṣati", "sa": "काङ्क्षति", "gram": "3 sg. pres. act.", "es": "desea", "analisis": "√kāṅkṣ (desear, anhelar)"}, {"iast": "śubhāśubha-parityāgī", "sa": "शुभाशुभपरित्यागी", "gram": "nom. sg. m. adj.", "es": "que ha abandonado lo bueno y lo malo", "ref": "tyaga", "analisis": "śubha (bueno, propicio) + aśubha (malo) + parityāgin (que abandona)"}, {"iast": "bhaktimān", "sa": "भक्तिमान्", "gram": "nom. sg. m. adj.", "es": "lleno de devoción", "ref": "bhakti", "analisis": "bhakti + -mat (que posee)"}, {"iast": "saḥ", "sa": "सः", "gram": "nom. sg. m. pron.", "es": "ése"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "me"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m. adj.", "es": "querido"}], "nota": "<p>Cuatro negaciones seguidas, dos frente a lo que llega y dos frente a lo que falta. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> las explican así: no se alegra al obtener lo deseado, no odia al recibir lo no deseado, no se aflige al perder lo querido y no ansía lo que no tiene. «Lo bueno y lo malo» (<em>śubhāśubha</em>) no son aquí el bien y el mal morales en abstracto, sino las obras buenas y malas: así lo entienden Śaṅkara («las acciones buenas y malas»), <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> («el mérito y el pecado») y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> («las acciones que producen placer y dolor»). Es la idea de <a class=\"vref\" href=\"capitulo-02.html#v50\" data-v=\"2.50\">2.50</a>: el que está unido al entendimiento deja atrás tanto la buena acción como la mala. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> da la razón: el mérito ata igual que el pecado.</p>", "interp": [{"titulo": "Un verso que explica otros", "html": "<p><a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lee el verso como comentario de rasgos ya dichos: las cuatro negaciones desarrollan el «igual en el dolor y en el placer» de <a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>, y el abandono de lo bueno y lo malo, el abandono de toda empresa de <a class=\"vref\" href=\"capitulo-12.html#v16\" data-v=\"12.16\">12.16</a>.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-devoto-que-me-es-querido"}, {"n": 18, "hablante": "krsna", "sa": ["समः शत्रौ च मित्रे च तथा मानापमानयोः ।", "शीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः ॥१८॥"], "iast": ["samaḥ śatrau ca mitre ca tathā mānāpamānayoḥ", "śītoṣṇa-sukha-duḥkheṣu samaḥ saṅga-vivarjitaḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Igual ante el enemigo y ante el amigo, y también en la honra y en la deshonra; igual en el frío y el calor, en el <a class=\"t\" href=\"glosario.html#sukha\" data-t=\"sukha\">placer</a> y el <a class=\"t\" href=\"glosario.html#duhkha\" data-t=\"duhkha\">dolor</a>; libre de apego;</span>", "palabras": [{"iast": "samaḥ", "sa": "समः", "gram": "nom. sg. m. adj.", "es": "igual", "ref": "samatva"}, {"iast": "śatrau", "sa": "शत्रौ", "gram": "loc. sg. m.", "es": "ante el enemigo"}, {"iast": "ca", "sa": "च", "gram": "conj.", "es": "y"}, {"iast": "mitre", "sa": "मित्रे", "gram": "loc. sg. m.", "es": "ante el amigo"}, {"iast": "tathā", "sa": "तथा", "gram": "adv.", "es": "y también, así"}, {"iast": "mānāpamānayoḥ", "sa": "मानापमानयोः", "gram": "loc. du. m.", "es": "en la honra y en la deshonra", "analisis": "māna (honra) + apamāna (deshonra)"}, {"iast": "śītoṣṇa-sukha-duḥkheṣu", "sa": "शीतोष्णसुखदुःखेषु", "gram": "loc. pl. n.", "es": "en el frío y el calor, el placer y el dolor", "ref": "dvandva", "analisis": "śīta (frío) + uṣṇa (calor) + sukha (placer) + duḥkha (dolor)"}, {"iast": "saṅga-vivarjitaḥ", "sa": "सङ्गविवर्जितः", "gram": "nom. sg. m. adj.", "es": "libre de apego", "analisis": "saṅga (apego) + vivarjita (privado, libre)"}], "nota": "<p>Una nueva frase, que se extiende por dos versos y termina en <a class=\"vref\" href=\"capitulo-12.html#v19\" data-v=\"12.19\">12.19</a>. Casi todo lo que dice tiene precedente o eco en la Gītā. El frío y el calor, el placer y el dolor eran en <a class=\"vref\" href=\"capitulo-02.html#v14\" data-v=\"2.14\">2.14</a> los contactos pasajeros que hay que soportar, y en <a class=\"vref\" href=\"capitulo-06.html#v7\" data-v=\"6.7\">6.7</a> iban ya con la honra y la deshonra. La igualdad ante el amigo y el enemigo es la de <a class=\"vref\" href=\"capitulo-06.html#v9\" data-v=\"6.9\">6.9</a>. Y <a class=\"vref\" href=\"capitulo-14.html#v24\" data-v=\"14.24\">14.24</a>–<a class=\"vref\" href=\"capitulo-14.html#v25\" data-v=\"14.25\">14.25</a> repetirán parte de la serie, a veces con las mismas palabras (la honra y la deshonra, el amigo y el enemigo, la censura y el elogio), para describir al que ha ido más allá de las tres <a class=\"t\" href=\"glosario.html#guna\" data-t=\"guna\">guṇas</a>. La edición crítica lee <em>mānāvamānayoḥ</em>, de igual sentido; la vulgata, <em>mānāpamānayoḥ</em>.</p>", "interp": [{"titulo": "Lo que añade este verso", "html": "<p><a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> explica por qué el retrato vuelve sobre amigos y enemigos, si ya se dijo que el devoto no odia a nadie (<a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>): allí se trataba de no odiar; aquí, de mantener la mente igual aun cuando el amigo o el enemigo están presentes. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a>, en cambio, se limita a decir que el verso desarrolla lo anterior, y entiende el apego como dar por hermoso cualquier objeto, animado o inanimado.</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-devoto-que-me-es-querido"}, {"n": 19, "hablante": "krsna", "sa": ["तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येन केनचित् ।", "अनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः ॥१९॥"], "iast": ["tulya-nindā-stutir maunī santuṣṭo yena kenacit", "aniketaḥ sthira-matir bhaktimān me priyo naraḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">para quien son lo mismo la censura y el elogio, callado, contento con cualquier cosa, <a class=\"t\" href=\"glosario.html#aniketa\" data-t=\"aniketa\">sin morada fija</a>, de pensamiento firme, lleno de <a class=\"t\" href=\"glosario.html#bhakti\" data-t=\"bhakti\">devoción</a>: ese hombre me es querido.</span>", "palabras": [{"iast": "tulya-nindā-stutiḥ", "sa": "तुल्यनिन्दास्तुतिः", "gram": "nom. sg. m. adj.", "es": "para quien son lo mismo la censura y el elogio", "analisis": "tulya (igual) + nindā (censura) + stuti (elogio)"}, {"iast": "maunī", "sa": "मौनी", "gram": "nom. sg. m. adj.", "es": "callado", "ref": "muni", "analisis": "maunin, de mauna (silencio), derivado de muni"}, {"iast": "santuṣṭaḥ", "sa": "सन्तुष्टः", "gram": "nom. sg. m. part. pas.", "es": "contento"}, {"iast": "yena kenacit", "sa": "येन केनचित्", "gram": "instr. sg. n. indef.", "es": "con cualquier cosa", "analisis": "yena (con lo que) + kena-cit (con algo)"}, {"iast": "aniketaḥ", "sa": "अनिकेतः", "gram": "nom. sg. m. adj.", "es": "sin morada fija", "ref": "aniketa", "analisis": "a- (sin) + niketa (morada, casa)"}, {"iast": "sthira-matiḥ", "sa": "स्थिरमतिः", "gram": "nom. sg. m. adj.", "es": "de pensamiento firme", "analisis": "sthira (firme) + mati (pensamiento, juicio)"}, {"iast": "bhaktimān", "sa": "भक्तिमान्", "gram": "nom. sg. m. adj.", "es": "lleno de devoción", "ref": "bhakti"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "me"}, {"iast": "priyaḥ", "sa": "प्रियः", "gram": "nom. sg. m. adj.", "es": "querido"}, {"iast": "naraḥ", "sa": "नरः", "gram": "nom. sg. m.", "es": "hombre"}], "nota": "<p><em>Maunī</em>, «callado», es de la familia de <a class=\"t\" href=\"glosario.html#muni\" data-t=\"muni\">muni</a>, el sabio que guarda silencio. <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo glosan como «el que refrena la palabra»; Madhusūdana aclara que no se trata de no hablar en absoluto, porque hace falta hablar para mantener el cuerpo. «Contento con cualquier cosa» repite el <em>santuṣṭa</em> de <a class=\"vref\" href=\"capitulo-12.html#v14\" data-v=\"12.14\">12.14</a> y recuerda <a class=\"vref\" href=\"capitulo-04.html#v22\" data-v=\"4.22\">4.22</a>, «contento con lo que le llega sin buscarlo». Para ilustrarlo, Śaṅkara cita un verso que se lee en el <em>Mahābhārata</em>: «al que se cubre con cualquier cosa, se alimenta con cualquier cosa y duerme en cualquier sitio, los dioses lo tienen por brahmán». <em>Bhaktimān</em>, «lleno de devoción», aparece por segunda vez (<a class=\"vref\" href=\"capitulo-12.html#v17\" data-v=\"12.17\">12.17</a>); Madhusūdana explica que el texto repite una y otra vez la devoción para dejar firme que ella es la causa plena de la liberación.</p>", "interp": [], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "alt": [{"html": "para quien son lo mismo la censura y el elogio, callado, contento con cualquier cosa, sin apego a su casa, de pensamiento firme, lleno de devoción: ese hombre me es querido.", "nota": "<p><em>Aniketa</em> es literalmente «sin casa». <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo entienden a la letra: el que no tiene residencia fija, como el renunciante errante. <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> lo entiende como el que no está apegado a su casa ni a nada semejante, porque tiene la mente firme en el sí-mismo; también Prabhupāda: puede vivir bajo un árbol o en un palacio, y nada de eso lo atrae (véase la ficha <a class=\"t\" href=\"glosario.html#aniketa\" data-t=\"aniketa\">aniketa</a>).</p>"}], "ens": "el-devoto-que-me-es-querido"}, {"n": 20, "hablante": "krsna", "sa": ["ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते ।", "श्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः ॥२०॥"], "iast": ["ye tu dharmyāmṛtam idaṃ yathoktaṃ paryupāsate", "śraddadhānā mat-paramā bhaktās te 'tīva me priyāḥ"], "rojas": [0, 1], "t": "<span class=\"vt-parte voz-krsna\">Pero los que, con <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a> y teniéndome por meta suprema, hacen suyo este <a class=\"t\" href=\"glosario.html#amrta\" data-t=\"amrta\">néctar</a> conforme al <a class=\"t\" href=\"glosario.html#dharma\" data-t=\"dharma\">dharma</a> tal como lo he expuesto, esos <a class=\"t\" href=\"glosario.html#bhakta\" data-t=\"bhakta\">devotos</a> me son sumamente queridos.</span>", "palabras": [{"iast": "ye", "sa": "ये", "gram": "nom. pl. m. rel.", "es": "los que"}, {"iast": "tu", "sa": "तु", "gram": "part.", "es": "pero"}, {"iast": "dharmyāmṛtam", "sa": "धर्म्यामृतम्", "gram": "acc. sg. n.", "es": "néctar conforme al dharma", "ref": "amrta", "analisis": "dharmya (conforme al dharma) + amṛta (néctar, inmortalidad)"}, {"iast": "idam", "sa": "इदम्", "gram": "acc. sg. n. pron.", "es": "este"}, {"iast": "yathoktam", "sa": "यथोक्तम्", "gram": "adv.", "es": "tal como se ha dicho", "analisis": "yathā (como) + ukta (dicho), √vac"}, {"iast": "paryupāsate", "sa": "पर्युपासते", "gram": "3 pl. pres. med.", "es": "hacen suyo, practican, adoran", "ref": "upasana", "analisis": "pari-upa-√ās (sentarse junto a: servir, venerar)"}, {"iast": "śraddadhānāḥ", "sa": "श्रद्दधानाः", "gram": "nom. pl. m. part. pres.", "es": "con fe", "ref": "sraddha", "analisis": "śrad-√dhā (poner fe)"}, {"iast": "mat-paramāḥ", "sa": "मत्परमाः", "gram": "nom. pl. m. adj.", "es": "que me tienen por meta suprema", "analisis": "mad (yo) + parama (lo supremo)"}, {"iast": "bhaktāḥ", "sa": "भक्ताः", "gram": "nom. pl. m.", "es": "devotos", "ref": "bhakta"}, {"iast": "te", "sa": "ते", "gram": "nom. pl. m. pron.", "es": "esos"}, {"iast": "atīva", "sa": "अतीव", "gram": "adv.", "es": "sumamente", "analisis": "ati (más allá) + iva"}, {"iast": "me", "sa": "मे", "gram": "gen. sg. pron.", "es": "me"}, {"iast": "priyāḥ", "sa": "प्रियाः", "gram": "nom. pl. m. adj.", "es": "queridos"}], "nota": "<p>El último verso cierra el capítulo con las palabras con que se abrió: <em>ye … paryupāsate</em>, «los que adoran», es la fórmula de la pregunta de Arjuna en <a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a> y de <a class=\"vref\" href=\"capitulo-12.html#v3\" data-v=\"12.3\">12.3</a>, que también empieza con <em>ye tu</em>, «pero los que». Aquí el objeto no es una forma de Dios sino la enseñanza misma, y <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> glosan el verbo como «practican»; de ahí «hacen suyo». <em>Dharmyāmṛta</em> lo deshacen Śaṅkara y <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> como «conforme al dharma y néctar»; Śaṅkara explica que se llama néctar (<em>amṛta</em>, también «inmortalidad») porque es causa de la inmortalidad, y Madhusūdana, que lo entiende como «el néctar que consiste en el dharma», añade «o porque se saborea como el néctar». Śrīdhara comenta otra lectura, <em>dharmāmṛtam</em>, «el dharma que es néctar», y anota que algunos leen <em>dharmyāmṛtam</em>, la de la vulgata. El estribillo culmina: «me es querido» pasa a «me son sumamente queridos».</p>", "interp": [{"titulo": "Lo que el sabio es y el buscador practica", "html": "<p>Para <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a>, «los que» son de nuevo los renunciantes, y son devotos porque han tomado «la devoción suprema, que consiste en el conocimiento de la realidad suprema»; el verso concluye lo que se anunció en <a class=\"vref\" href=\"capitulo-07.html#v17\" data-v=\"7.17\">7.17</a>. De ahí su enseñanza: puesto que quien practica este néctar se vuelve sumamente querido a Viṣṇu, el que busca la liberación ha de practicarlo con empeño. <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> lo formula con una cita de Sureśvara: en quien ha despertado al sí-mismo, el no odiar y las demás cualidades surgen sin esfuerzo, no como medios; son las mismas que el capítulo 2 dio como señales del <a class=\"t\" href=\"glosario.html#sthitaprajna\" data-t=\"sthitaprajna\">de sabiduría firme</a>. Lo que en el sabio es natural, el que busca la liberación lo cultiva con esfuerzo, y para él es el medio.</p>", "trad": "advaita", "tradNombre": "Advaita Vedānta"}, {"titulo": "El devoto que es más querido", "html": "<p>Para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a>, el verso separa a dos clases de devotos. Los de <a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>–<a class=\"vref\" href=\"capitulo-12.html#v19\" data-v=\"12.19\">12.19</a> son los que siguen el <em>karma-yoga</em> y tienen el sí-mismo por objeto; los de este verso, los que practican el yoga de la devoción tal como se enseñó desde <a class=\"vref\" href=\"capitulo-12.html#v2\" data-v=\"12.2\">12.2</a>, y por eso son «sumamente» queridos. Así el capítulo termina como empezó, mostrando la superioridad del devoto. Rāmānuja llama a este yoga de la devoción un medio igual a la meta: tan deseable como lo que alcanza. Vedānta Deśika apoya la lectura en tres indicios del texto: el <em>tu</em>, el «que me tienen por meta suprema» y el «sumamente».</p>", "trad": "visistadvaita", "tradNombre": "Viśiṣṭādvaita"}, {"titulo": "Dharma es Viṣṇu", "html": "<p><a class=\"t\" href=\"glosario.html#madhva\" data-t=\"madhva\">Madhva</a> da a <em>dharmya</em> otro sentido: <em>dharma</em> es aquí un nombre de Viṣṇu, y <em>dharmya</em> es «lo que se refiere a él». <em>Amṛta</em> es lo que destruye la existencia en el mundo, que empieza con la muerte. Jayatīrtha precisa que el compuesto es un <em>karmadhāraya</em>: el néctar que se refiere a Viṣṇu.</p>", "trad": "dvaita", "tradNombre": "Dvaita"}, {"titulo": "El camino de la devoción, el mejor", "html": "<p>Prabhupāda, que lee <em>dharmāmṛtam</em>, ve en este verso la conclusión del capítulo entero, desde <a class=\"vref\" href=\"capitulo-12.html#v2\" data-v=\"12.2\">12.2</a>: a la pregunta de Arjuna sobre qué es mejor, el camino del brahman impersonal o el servicio personal al Señor, Kṛṣṇa ha respondido de modo tan explícito que no queda duda de que el servicio devocional es el mejor de todos los procesos de realización espiritual.</p>", "trad": "gaudiya", "tradNombre": "Vaiṣṇavismo gauḍīya"}], "metro": "anuṣṭubh (śloka: cuatro pies de ocho sílabas)", "ens": "el-nectar-del-dharma"}], "ensenanzas": [{"id": "dos-maneras-de-adorar", "desde": 2, "hasta": 5, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Dos maneras de adorar: a él o a lo imperecedero", "resumen": "<p>Arjuna pregunta quiénes conocen mejor el yoga: los que adoran a Kṛṣṇa o los que adoran lo imperecedero, lo no manifiesto (<a class=\"vref\" href=\"capitulo-12.html#v1\" data-v=\"12.1\">12.1</a>). Kṛṣṇa responde en dos tiempos. Los que hacen entrar en él la mente y lo veneran con una fe suprema son para él los más unidos en yoga (<a class=\"vref\" href=\"capitulo-12.html#v2\" data-v=\"12.2\">12.2</a>); pero también los que adoran lo imperecedero, con los sentidos sujetos, ecuánimes y entregados al bien de todos, llegan a él (<a class=\"vref\" href=\"capitulo-12.html#v3\" data-v=\"12.3\">12.3</a>–<a class=\"vref\" href=\"capitulo-12.html#v4\" data-v=\"12.4\">12.4</a>). La diferencia está en el esfuerzo: lo no manifiesto es una meta difícil para quien tiene cuerpo (<a class=\"vref\" href=\"capitulo-12.html#v5\" data-v=\"12.5\">12.5</a>). Qué es ese imperecedero, y si los dos grupos llegan de verdad al mismo lugar, lo responden las escuelas de manera distinta; para <a class=\"t\" href=\"glosario.html#ramanuja\" data-t=\"ramanuja\">Rāmānuja</a> y <a class=\"t\" href=\"glosario.html#sridhara\" data-t=\"sridhara\">Śrīdhara Svāmī</a>, el resto del capítulo desarrolla el primer camino, mientras que <a class=\"t\" href=\"glosario.html#sankara\" data-t=\"sankara\">Śaṅkara</a> y <a class=\"t\" href=\"glosario.html#madhusudana-sarasvati\" data-t=\"madhusudana-sarasvati\">Madhusūdana Sarasvatī</a> ven en el retrato final (<a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>–<a class=\"vref\" href=\"capitulo-12.html#v19\" data-v=\"12.19\">12.19</a>) el de los que adoran lo imperecedero.</p>"}, {"id": "el-que-rescata", "desde": 6, "hasta": 7, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Kṛṣṇa mismo rescata a quien se entrega a él", "resumen": "<p>A los que depositan en él todas sus acciones, lo tienen por meta suprema y lo adoran sin dirigirse a ningún otro, Kṛṣṇa mismo los saca sin tardanza del océano del <a class=\"t\" href=\"glosario.html#samsara\" data-t=\"samsara\">saṃsāra</a> (<a class=\"vref\" href=\"capitulo-12.html#v6\" data-v=\"12.6\">12.6</a>–<a class=\"vref\" href=\"capitulo-12.html#v7\" data-v=\"12.7\">12.7</a>). Frente al camino arduo de quien adora lo imperecedero no manifiesto (<a class=\"vref\" href=\"capitulo-12.html#v5\" data-v=\"12.5\">12.5</a>), el del devoto no descansa en su propio esfuerzo, sino en el Señor que lo rescata.</p>"}, {"id": "escala-de-caminos", "desde": 8, "hasta": 12, "tipo": "tecnica", "tipoNombre": "Técnica", "titulo": "Una escala de caminos según lo que cada uno puede", "resumen": "<p>Kṛṣṇa propone cuatro caminos, cada uno para quien no puede el anterior: poner en él la mente y el entendimiento (<a class=\"vref\" href=\"capitulo-12.html#v8\" data-v=\"12.8\">12.8</a>); si no se logra, volver a él una y otra vez con el yoga de la <a class=\"t\" href=\"glosario.html#abhyasa\" data-t=\"abhyasa\">práctica</a> (<a class=\"vref\" href=\"capitulo-12.html#v9\" data-v=\"12.9\">12.9</a>); si tampoco, hacer las obras por él (<a class=\"vref\" href=\"capitulo-12.html#v10\" data-v=\"12.10\">12.10</a>); y si ni siquiera eso, abandonar el <a class=\"t\" href=\"glosario.html#phala\" data-t=\"phala\">fruto</a> de todas las acciones con la mente dominada (<a class=\"vref\" href=\"capitulo-12.html#v11\" data-v=\"12.11\">12.11</a>). Nadie queda sin camino. El verso final (<a class=\"vref\" href=\"capitulo-12.html#v12\" data-v=\"12.12\">12.12</a>) alaba el último escalón: del <a class=\"t\" href=\"glosario.html#tyaga\" data-t=\"tyaga\">abandono</a> del fruto viene en seguida la paz.</p>"}, {"id": "el-devoto-que-me-es-querido", "desde": 13, "hasta": 19, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "El devoto que Kṛṣṇa ama", "resumen": "<p>Kṛṣṇa describe en siete versos al <a class=\"t\" href=\"glosario.html#bhakta\" data-t=\"bhakta\">devoto</a> que le es querido. No odia a ningún ser; es amistoso y compasivo, libre del «mío» y del sentido del yo, paciente y siempre contento (<a class=\"vref\" href=\"capitulo-12.html#v13\" data-v=\"12.13\">12.13</a>–<a class=\"vref\" href=\"capitulo-12.html#v14\" data-v=\"12.14\">12.14</a>). No inquieta a nadie ni se deja inquietar (<a class=\"vref\" href=\"capitulo-12.html#v15\" data-v=\"12.15\">12.15</a>). No espera nada y ha abandonado toda empresa (<a class=\"vref\" href=\"capitulo-12.html#v16\" data-v=\"12.16\">12.16</a>). No se alegra ni odia, no se aflige ni desea (<a class=\"vref\" href=\"capitulo-12.html#v17\" data-v=\"12.17\">12.17</a>). Es igual ante el amigo y el enemigo, la honra y la deshonra, el frío y el calor, la censura y el elogio; callado, contento con cualquier cosa, sin morada fija y de pensamiento firme (<a class=\"vref\" href=\"capitulo-12.html#v18\" data-v=\"12.18\">12.18</a>–<a class=\"vref\" href=\"capitulo-12.html#v19\" data-v=\"12.19\">12.19</a>). Cada retrato termina con el mismo estribillo: «ése me es querido». La devoción del capítulo no es un sentimiento, sino una manera de estar en el mundo.</p>"}, {"id": "el-nectar-del-dharma", "desde": 20, "hasta": 20, "tipo": "concepto", "tipoNombre": "Concepto", "titulo": "Hacer propio el néctar del dharma", "resumen": "<p>Los que, con <a class=\"t\" href=\"glosario.html#sraddha\" data-t=\"sraddha\">fe</a> y teniendo a Kṛṣṇa por meta suprema, hacen suya esta enseñanza tal como la ha expuesto, le son «sumamente» queridos (<a class=\"vref\" href=\"capitulo-12.html#v20\" data-v=\"12.20\">12.20</a>). El rasgo que corona el retrato del devoto es practicarlo: Kṛṣṇa llama a la enseñanza <a class=\"t\" href=\"glosario.html#amrta\" data-t=\"amrta\">néctar</a> conforme al dharma, lo que da la inmortalidad. Para Śaṅkara y Madhusūdana, lo que en el sabio es natural se convierte para el que busca en el camino; para Rāmānuja, el verso distingue al devoto entregado a la devoción misma, el más querido de todos.</p>"}]};
